def get_workspaces(connection_id, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0487000" if __import__("os").path.isdir("./environment_mix/0487000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_workspaces"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, connection_used, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{_now()}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24].upper(),
            "endpoint": endpoint,
            "connection_id": connection_used,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now()
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_rate_limit(conn_id):
        # "maximum Clockify API calls per minute" (applied to tools here as integration calls)
        settings = _load("settings.json")
        max_per_min = None
        if isinstance(settings, dict):
            v = settings.get("max_api_calls_per_minute")
            if isinstance(v, int) and v > 0:
                max_per_min = v
        if max_per_min is None:
            max_per_min = 120  # reasonable default when enabled/unknown

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(minutes=1)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict): 
                continue
            if r.get("connection_id") != conn_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                if dt.tzinfo is not None:
                    dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= max_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded for connection", limit=max_per_min, window_seconds=60)
        return None

    def _parse_cursor(cur):
        # Opaque cursor: base64url("v1:<offset>")
        if cur is None:
            return 0
        if not isinstance(cur, str) or cur.strip() == "":
            return None
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("utf-8")).decode("utf-8")
            if not raw.startswith("v1:"):
                return None
            off = int(raw.split(":", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _make_cursor(off):
        raw = f"v1:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate
    if not isinstance(connection_id, str) or re.match(r"^clk_conn_[0-9A-Z]+$", connection_id) is None:
        _log(400, connection_id if isinstance(connection_id, str) else None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "connection_id is malformed")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived"):
            _log(400, connection_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: active, archived")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(400, connection_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    offset = _parse_cursor(cursor)
    if offset is None:
        _log(400, connection_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor is invalid")

    # Auth/context: require that the specified connection exists and is active
    conns = _load("clockify_connections.json")
    conn = None
    if isinstance(conns, list):
        for c in conns:
            if isinstance(c, dict) and c.get("id") == connection_id:
                conn = c
                break
    if conn is None:
        _log(404, connection_id, "NOT_FOUND")
        return _err("NOT_FOUND", "connection_id not found")
    if conn.get("status") != "active":
        _log(401, connection_id, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Clockify connection is not active")

    rl = _enforce_rate_limit(connection_id)
    if rl is not None:
        _log(429, connection_id, "RATE_LIMIT")
        return rl

    # Query
    wss = _load("workspaces.json")
    if not isinstance(wss, list):
        wss = []

    rows = []
    for w in wss:
        if not isinstance(w, dict):
            continue
        if w.get("connection_id") != connection_id:
            continue
        if status is not None and w.get("status") != status:
            continue
        rows.append(w)

    # Deterministic ordering by name then id
    def _key(w):
        nm = w.get("name")
        return ((nm or "").lower(), w.get("id") or "")
    rows.sort(key=_key)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    # Redact any sensitive fields (none in workspace rows, but keep safe)
    def _public_ws(w):
        return {
            "id": w.get("id"),
            "connection_id": w.get("connection_id"),
            "external_workspace_id": w.get("external_workspace_id"),
            "name": w.get("name"),
            "membership_role": w.get("membership_role"),
            "status": w.get("status"),
            "synced_at": w.get("synced_at"),
            "created_at": w.get("created_at"),
            "updated_at": w.get("updated_at"),
        }

    resp = {
        "data": [_public_ws(w) for w in page],
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }
    _log(200, connection_id, None)
    return resp

