def get_user(connection_id, workspace_id=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0487000" if __import__("os").path.isdir("./environment_mix/0487000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_user"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, connection_used, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": "req_" + hashlib.sha256(f"{endpoint}|{_now()}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24].upper(),
            "endpoint": endpoint,
            "connection_id": connection_used,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now()
        })
        _save("request_logs.json", logs)

    def _enforce_rate_limit(conn_id):
        settings = _load("settings.json")
        max_per_min = None
        if isinstance(settings, dict):
            v = settings.get("max_api_calls_per_minute")
            if isinstance(v, int) and v > 0:
                max_per_min = v
        if max_per_min is None:
            max_per_min = 120

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(minutes=1)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict): 
                continue
            if r.get("connection_id") != conn_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                if dt.tzinfo is not None:
                    dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= max_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded for connection", limit=max_per_min, window_seconds=60)
        return None

    def _gen_id(prefix):
        return prefix + hashlib.sha256(f"{prefix}|{_now()}|{time.time_ns()}".encode("utf-8")).hexdigest()[:16].upper()

    # Validate
    if not isinstance(connection_id, str) or re.match(r"^clk_conn_[0-9A-Z]+$", connection_id) is None:
        _log(400, connection_id if isinstance(connection_id, str) else None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "connection_id is malformed")
    if workspace_id is not None:
        if not isinstance(workspace_id, str) or re.match(r"^clk_wsp_[0-9A-Z]+$", workspace_id) is None:
            _log(400, connection_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workspace_id is malformed")

    conns = _load("clockify_connections.json")
    if not isinstance(conns, list): conns = []
    conn = None
    for c in conns:
        if isinstance(c, dict) and c.get("id") == connection_id:
            conn = c
            break
    if conn is None:
        _log(404, connection_id, "NOT_FOUND")
        return _err("NOT_FOUND", "connection_id not found")
    if conn.get("status") != "active":
        _log(401, connection_id, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Clockify connection is not active")

    rl = _enforce_rate_limit(connection_id)
    if rl is not None:
        _log(429, connection_id, "RATE_LIMIT")
        return rl

    # Resolve workspace scope: explicit workspace_id, else default_workspace_id, else first active by name.
    wss = _load("workspaces.json")
    if not isinstance(wss, list): wss = []

    def _ws_sort_key(w):
        return ((w.get("name") or "").lower(), w.get("id") or "")

    selected_ws = None
    if workspace_id is not None:
        for w in wss:
            if isinstance(w, dict) and w.get("id") == workspace_id and w.get("connection_id") == connection_id:
                selected_ws = w
                break
        if selected_ws is None:
            _log(404, connection_id, "NOT_FOUND")
            return _err("NOT_FOUND", "workspace_id not found or not accessible to this connection")
    else:
        def_id = conn.get("default_workspace_id")
        if isinstance(def_id, str):
            for w in wss:
                if isinstance(w, dict) and w.get("id") == def_id and w.get("connection_id") == connection_id:
                    selected_ws = w
                    break
        if selected_ws is None:
            candidates = [w for w in wss if isinstance(w, dict) and w.get("connection_id") == connection_id and w.get("status") == "active"]
            candidates.sort(key=_ws_sort_key)
            selected_ws = candidates[0] if candidates else None

    if selected_ws is None:
        _log(401, connection_id, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible workspace for this connection")

    # Upsert user entity in the selected workspace based on external_user_id
    ents = _load("workspace_entities.json")
    if not isinstance(ents, list): ents = []

    ext_user_id = conn.get("external_user_id")
    if not isinstance(ext_user_id, str) or ext_user_id.strip() == "":
        _log(409, connection_id, "CONFLICT")
        return _err("CONFLICT", "Connection is missing external_user_id mapping")

    user_row = None
    for e in ents:
        if not isinstance(e, dict):
            continue
        if e.get("workspace_id") != selected_ws.get("id"):
            continue
        if e.get("entity_type") != "user":
            continue
        if e.get("external_id") == ext_user_id:
            user_row = e
            break

    now = _now()
    mutated = False
    if user_row is None:
        # Ensure uniqueness (workspace_id, entity_type, external_id)
        new_id = _gen_id("clk_ent_")
        user_row = {
            "id": new_id,
            "workspace_id": selected_ws.get("id"),
            "entity_type": "user",
            "external_id": ext_user_id,
            "name": None,
            "email": conn.get("external_user_email"),
            "project_id": None,
            "client_id": None,
            "billable": None,
            "archived": None,
            "color": None,
            "status": "active",
            "raw": None,
            "created_at": now,
            "updated_at": now
        }
        ents.append(user_row)
        mutated = True
    else:
        # update email if missing
        if (user_row.get("email") in (None, "")) and isinstance(conn.get("external_user_email"), str) and conn.get("external_user_email"):
            user_row["email"] = conn.get("external_user_email")
            user_row["updated_at"] = now
            mutated = True
        # If user was archived, keep as-is; business rules didn't require re-activate.

    if mutated:
        _save("workspace_entities.json", ents)

    resp = {
        "data": {
            "connection_id": connection_id,
            "workspace": {
                "id": selected_ws.get("id"),
                "name": selected_ws.get("name"),
                "external_workspace_id": selected_ws.get("external_workspace_id"),
                "membership_role": selected_ws.get("membership_role"),
                "status": selected_ws.get("status"),
            },
            "user": {
                "id": user_row.get("id"),
                "workspace_id": user_row.get("workspace_id"),
                "external_id": user_row.get("external_id"),
                "email": user_row.get("email"),
                "name": user_row.get("name"),
                "status": user_row.get("status"),
                "created_at": user_row.get("created_at"),
                "updated_at": user_row.get("updated_at"),
            }
        }
    }
    _log(200, connection_id, None)
    return resp

