        _log(401, conn_id if isinstance(conn_id, str) else None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Clockify connection is not active for this workspace")

    rl = _enforce_rate_limit(conn_id)
    if rl is not None:
        _log(429, conn_id, "RATE_LIMIT")
        return rl

    ents = _load("workspace_entities.json")
    if not isinstance(ents, list): ents = []

    rows = []
    for e in ents:
        if not isinstance(e, dict):
            continue
        if e.get("workspace_id") != workspace_id:
            continue
        if e.get("entity_type") != "user":
            continue
        if status is not None and e.get("status") != status:
            continue
        rows.append(e)

    # deterministic order: email then name then id
    def _k(e):
        return ((e.get("email") or "").lower(), (e.get("name") or "").lower(), e.get("id") or "")
    rows.sort(key=_k)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    def _public_user(e):
        return {
            "id": e.get("id"),
            "workspace_id": e.get("workspace_id"),
            "entity_type": e.get("entity_type"),
            "external_id": e.get("external_id"),
            "name": e.get("name"),
            "email": e.get("email"),
            "status": e.get("status"),
            "raw": e.get("raw"),
            "created_at": e.get("created_at"),
            "updated_at": e.get("updated_at"),
        }

    resp = {
        "data": [_public_user(e) for e in page],
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }
    _log(200, conn_id, None)
    return resp

