            break

    # Prepare request log entry helper
    def _log(status_code, error_code=None, error_message=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        entry = {
            "id": "req_" + hashlib.sha256((now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24],
            "endpoint": "get_clients",
            "connection_id": active_conn.get("id") if isinstance(active_conn, dict) else None,
            "status": status_code,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        }
        if isinstance(extra, dict):
            entry.update(extra)
        logs.append(entry)
        _save("request_logs.json", logs)

    if active_conn is None:
        _log(401, "UNAUTHORIZED", "No active Clockify connection.")
        return _err("UNAUTHORIZED", "No active Clockify connection.")

    # --- basic rate limit / quota enforcement (best-effort, if usage policies file exists) ---
    policies = _load("usage_policies.json")
    if isinstance(policies, dict):
        api_per_min = policies.get("max_api_calls_per_minute")
        if isinstance(api_per_min, int) and api_per_min > 0:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            cutoff = (datetime.datetime.utcnow() - datetime.timedelta(minutes=1)).replace(microsecond=0).isoformat() + "Z"
            recent = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("connection_id") != active_conn.get("id"):
                    continue
                ts = r.get("created_at")
                if isinstance(ts, str) and ts >= cutoff:
                    recent += 1
            if recent >= api_per_min:
                _log(429, "RATE_LIMIT", "API rate limit exceeded.")
                return _err("RATE_LIMIT", "API rate limit exceeded.", limit=api_per_min, window_seconds=60)

    # --- validate inputs ---
    if not isinstance(workspace_id, str) or not re.match(r"^clk_wsp_[0-9A-Z]+$", workspace_id):
        _log(400, "VALIDATION_ERROR", "workspace_id is invalid.")
        return _err("VALIDATION_ERROR", "workspace_id is invalid.")
    if archived is not None and not isinstance(archived, bool):
        _log(400, "VALIDATION_ERROR", "archived must be boolean.")
        return _err("VALIDATION_ERROR", "archived must be boolean.")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            _log(400, "VALIDATION_ERROR", "status is invalid.")
            return _err("VALIDATION_ERROR", "status is invalid.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(400, "VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        _log(400, "VALIDATION_ERROR", "cursor must be a string.")
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    start = 0
    if cursor:
        # cursor is opaque; we accept base64url("offset:<int>") or raw integer strings
        parsed = None
        if cursor.isdigit():
            parsed = int(cursor)
        else:
            try:
                pad = "=" * (-len(cursor) % 4)
                dec = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8", "strict")
                if dec.startswith("offset:") and dec[7:].isdigit():
                    parsed = int(dec[7:])
            except Exception:
                parsed = None
        if parsed is None or parsed < 0:
            _log(400, "VALIDATION_ERROR", "cursor is invalid.")
            return _err("VALIDATION_ERROR", "cursor is invalid.")
        start = parsed

    # --- load and authorize workspace ---
    workspaces = _load("workspaces.json")
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == workspace_id and w.get("connection_id") == active_conn.get("id"):
            ws = w
            break
    if ws is None:
        _log(404, "NOT_FOUND", "Workspace not found or not accessible.")
        return _err("NOT_FOUND", "Workspace not found or not accessible.")

    # --- query entities ---
    ents = _load("workspace_entities.json")
    rows = []
    for e in ents:
        if not isinstance(e, dict):
            continue
        if e.get("workspace_id") != workspace_id:
            continue
        if e.get("entity_type") != "client":
            continue
        if archived is not None and e.get("archived") is not archived:
            continue
        if status is not None and e.get("status") != status:
            continue
        rows.append(e)

    # deterministic sort (name asc, then id)
    def _key(r):
        n = r.get("name")
        if not isinstance(n, str):
            n = ""
        return (n.lower(), n, r.get("id") or "")
    rows.sort(key=_key)

    total = len(rows)
    page = rows[start:start + limit]
    next_offset = start + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(("offset:%d" % next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    # sanitize response: never return api_key_ciphertext (not present here anyway); keep raw as stored
    _log(200)
    return {
        "clients": page,
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total
        }
    }

