        logs.append(entry)
        _save("request_logs.json", logs)

    if active_conn is None:
        _log(401, "UNAUTHORIZED", "No active Clockify connection.")
        return _err("UNAUTHORIZED", "No active Clockify connection.")

    # rate limit / quota enforcement (best-effort)
    policies = _load("usage_policies.json")
    if isinstance(policies, dict):
        api_per_min = policies.get("max_api_calls_per_minute")
        if isinstance(api_per_min, int) and api_per_min > 0:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            cutoff = (datetime.datetime.utcnow() - datetime.timedelta(minutes=1)).replace(microsecond=0).isoformat() + "Z"
            recent = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("connection_id") != active_conn.get("id"):
