                ts = r.get("created_at")
                if isinstance(ts, str) and ts >= cutoff:
                    recent += 1
            if recent >= api_per_min:
                _log(429, "RATE_LIMIT", "API rate limit exceeded.")
                return _err("RATE_LIMIT", "API rate limit exceeded.", limit=api_per_min, window_seconds=60)

    if not isinstance(workspace_id, str) or not re.match(r"^clk_wsp_[0-9A-Z]+$", workspace_id):
        _log(400, "VALIDATION_ERROR", "workspace_id is invalid.")
        return _err("VALIDATION_ERROR", "workspace_id is invalid.")
    if not isinstance(name, str) or len(name.strip()) < 1:
        _log(400, "VALIDATION_ERROR", "name is required.")
        return _err("VALIDATION_ERROR", "name is required.")
    name_norm = " ".join(name.strip().split())

    workspaces = _load("workspaces.json")
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == workspace_id and w.get("connection_id") == active_conn.get("id"):
            ws = w
            break
    if ws is None:
        _log(404, "NOT_FOUND", "Workspace not found or not accessible.")
        return _err("NOT_FOUND", "Workspace not found or not accessible.")

    ents = _load("workspace_entities.json")
    if not isinstance(ents, list):
        ents = []

    # conflict: same client name in workspace (case-insensitive) among non-deleted
    for e in ents:
        if not isinstance(e, dict):
            continue
        if e.get("workspace_id") != workspace_id or e.get("entity_type") != "client":
            continue
        en = e.get("name")
        if isinstance(en, str) and en.strip().lower() == name_norm.lower() and e.get("status") != "deleted":
            _log(409, "CONFLICT", "Client with the same name already exists.")
            return _err("CONFLICT", "Client with the same name already exists.", existing_id=e.get("id"))

    # id generation (ULID-ish, deterministic enough for offline)
    alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid(prefix):
        ts = int(now_dt.timestamp() * 1000)
        ts_part = ""
        x = ts
        for _ in range(10):
            ts_part = alphabet[x % 32] + ts_part
            x //= 32
        rand = hashlib.sha256((prefix + "|" + now + "|" + str(time.time())).encode("utf-8")).digest()
        r = ""
        for i in range(16):
            r += alphabet[rand[i] % 32]
        return prefix + ts_part + r

    new_id = _ulid("clk_ent_")
    external_id = "ext_" + hashlib.sha256((active_conn.get("id","") + "|" + workspace_id + "|client|" + new_id).encode("utf-8")).hexdigest()[:20]

    # "Create in Clockify" simulation: if connection is active, assume success and store provider payload snapshot.
    raw = {
        "provider": "clockify",
        "simulated": True,
        "created_at": now,
        "object": {"id": external_id, "name": name_norm}
    }

    row = {
        "id": new_id,
        "workspace_id": workspace_id,
        "entity_type": "client",
        "external_id": external_id,
        "name": name_norm,
        "email": None,
        "project_id": None,
        "client_id": None,
        "billable": None,
        "archived": False,
        "color": None,
        "status": "active",
        "raw": raw,
        "created_at": now,
        "updated_at": now
    }

    # uniqueness constraint: (workspace_id, entity_type, external_id)
    for e in ents:
        if not isinstance(e, dict):
            continue
        if e.get("workspace_id") == workspace_id and e.get("entity_type") == "client" and e.get("external_id") == external_id:
            _log(409, "CONFLICT", "Client external_id conflict.")
            return _err("CONFLICT", "Client external_id conflict.")

    ents.append(row)
    _save("workspace_entities.json", ents)

    # update connection last_success_at
    for c in conns:
        if isinstance(c, dict) and c.get("id") == active_conn.get("id"):
            c["last_success_at"] = now
            c["last_error_at"] = None
            c["last_error_message"] = None
            c["updated_at"] = now
            break
    _save("clockify_connections.json", conns)

    _log(201)
    return {"client": row}

