            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        }
        if isinstance(extra, dict):
            entry.update(extra)
        logs.append(entry)
        _save("request_logs.json", logs)

    if active_conn is None:
        _log(401, "UNAUTHORIZED", "No active Clockify connection.")
        return _err("UNAUTHORIZED", "No active Clockify connection.")

    policies = _load("usage_policies.json")
    if isinstance(policies, dict):
        api_per_min = policies.get("max_api_calls_per_minute")
        if isinstance(api_per_min, int) and api_per_min > 0:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            cutoff = (datetime.datetime.utcnow() - datetime.timedelta(minutes=1)).replace(microsecond=0).isoformat() + "Z"
            recent = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("connection_id") != active_conn.get("id"):
                    continue
                ts = r.get("created_at")
                if isinstance(ts, str) and ts >= cutoff:
                    recent += 1
            if recent >= api_per_min:
                _log(429, "RATE_LIMIT", "API rate limit exceeded.")
                return _err("RATE_LIMIT", "API rate limit exceeded.", limit=api_per_min, window_seconds=60)

    if not isinstance(workspace_id, str) or not re.match(r"^clk_wsp_[0-9A-Z]+$", workspace_id):
        _log(400, "VALIDATION_ERROR", "workspace_id is invalid.")
        return _err("VALIDATION_ERROR", "workspace_id is invalid.")
    if not isinstance(name, str) or len(name.strip()) < 1:
        _log(400, "VALIDATION_ERROR", "name is required.")
        return _err("VALIDATION_ERROR", "name is required.")
    name_norm = " ".join(name.strip().split())

    if client_id is not None:
        if not isinstance(client_id, str) or not re.match(r"^clk_ent_[0-9A-Z]+$", client_id):
            _log(400, "VALIDATION_ERROR", "client_id is invalid.")
            return _err("VALIDATION_ERROR", "client_id is invalid.")
    if billable is not None and not isinstance(billable, bool):
        _log(400, "VALIDATION_ERROR", "billable must be boolean.")
        return _err("VALIDATION_ERROR", "billable must be boolean.")
    if archived is not None and not isinstance(archived, bool):
        _log(400, "VALIDATION_ERROR", "archived must be boolean.")
        return _err("VALIDATION_ERROR", "archived must be boolean.")
    if color is not None and not isinstance(color, str):
        _log(400, "VALIDATION_ERROR", "color must be a string.")
        return _err("VALIDATION_ERROR", "color must be a string.")

    workspaces = _load("workspaces.json")
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == workspace_id and w.get("connection_id") == active_conn.get("id"):
            ws = w
            break
    if ws is None:
        _log(404, "NOT_FOUND", "Workspace not found or not accessible.")
        return _err("NOT_FOUND", "Workspace not found or not accessible.")

    ents = _load("workspace_entities.json")
    if not isinstance(ents, list):
        ents = []

    # validate client exists if provided and is correct type in same workspace
    if client_id is not None:
        client_row = None
        for e in ents:
            if isinstance(e, dict) and e.get("id") == client_id and e.get("workspace_id") == workspace_id:
                client_row = e
                break
        if client_row is None or client_row.get("entity_type") != "client":
            _log(404, "NOT_FOUND", "client_id not found in workspace.")
            return _err("NOT_FOUND", "client_id not found in workspace.")
        if client_row.get("status") == "deleted":
            _log(409, "CONFLICT", "Cannot attach deleted client.")
            return _err("CONFLICT", "Cannot attach deleted client.", client_id=client_id)

    # conflict: same project name in workspace (case-insensitive) among non-deleted
    for e in ents:
        if not isinstance(e, dict):
            continue
        if e.get("workspace_id") != workspace_id or e.get("entity_type") != "project":
            continue
        en = e.get("name")
        if isinstance(en, str) and en.strip().lower() == name_norm.lower() and e.get("status") != "deleted":
            _log(409, "CONFLICT", "Project with the same name already exists.")
            return _err("CONFLICT", "Project with the same name already exists.", existing_id=e.get("id"))

    alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid(prefix):
        ts = int(now_dt.timestamp() * 1000)
        ts_part = ""
        x = ts
        for _ in range(10):
            ts_part = alphabet[x % 32] + ts_part
            x //= 32
        rand = hashlib.sha256((prefix + "|" + now + "|" + str(time.time())).encode("utf-8")).digest()
        r = ""
        for i in range(16):
            r += alphabet[rand[i] % 32]
        return prefix + ts_part + r

    new_id = _ulid("clk_ent_")
    external_id = "ext_" + hashlib.sha256((active_conn.get("id","") + "|" + workspace_id + "|project|" + new_id).encode("utf-8")).hexdigest()[:20]

    if billable is None:
        billable_val = False
    else:
        billable_val = billable
    if archived is None:
        archived_val = False
    else:
        archived_val = archived

    raw = {
        "provider": "clockify",
        "simulated": True,
        "created_at": now,
        "object": {
            "id": external_id,
            "name": name_norm,
            "clientId": client_id,
            "billable": billable_val,
            "color": color,
            "archived": archived_val
        }
    }

    row = {
        "id": new_id,
        "workspace_id": workspace_id,
        "entity_type": "project",
        "external_id": external_id,
        "name": name_norm,
        "email": None,
        "project_id": None,
        "client_id": client_id,
        "billable": billable_val,
        "archived": archived_val,
        "color": color,
        "status": "archived" if archived_val else "active",
        "raw": raw,
        "created_at": now,
        "updated_at": now
    }

    # uniqueness constraint: (workspace_id, entity_type, external_id)
    for e in ents:
        if not isinstance(e, dict):
            continue
        if e.get("workspace_id") == workspace_id and e.get("entity_type") == "project" and e.get("external_id") == external_id:
            _log(409, "CONFLICT", "Project external_id conflict.")
            return _err("CONFLICT", "Project external_id conflict.")

    ents.append(row)
    _save("workspace_entities.json", ents)

    for c in conns:
        if isinstance(c, dict) and c.get("id") == active_conn.get("id"):
            c["last_success_at"] = now
            c["last_error_at"] = None
            c["last_error_message"] = None
            c["updated_at"] = now
            break
    _save("clockify_connections.json", conns)

    _log(201)
    return {"project": row}

def get_tasks(workspace_id, project_id, archived=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0487000" if __import__("os").path.isdir("./environment_mix/0487000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    # --- helpers ---
    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _log(endpoint, connection_id, status_code):
        # Best-effort request logging to a local file even if schema didn't declare it.
        # Enforces no quota unless a quotas collection exists.
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + hashlib.sha256(f"{endpoint}|{connection_id}|{now.isoformat()}|{time.time()}".encode("utf-8")).hexdigest()[:24],
                "endpoint": endpoint,
                "connection_id": connection_id,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _iso(now),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _active_connection():
        conns = _load("clockify_connections.json")
        if not isinstance(conns, list):
            conns = []
        actives = [c for c in conns if isinstance(c, dict) and c.get("provider") == "clockify" and c.get("status") == "active"]
        # choose deterministically (most recently updated, then id)
        def k(c):
            ud = _parse_dt(c.get("updated_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (ud, c.get("id") or "")
        actives.sort(key=k, reverse=True)
        return actives[0] if actives else None

    def _sanitize_entity(row):
        # workspace_entities has no secret fields; return as-is (copy).
        if not isinstance(row, dict):
            return None
        return dict(row)

    # --- validation ---
    ulid_wsp = re.compile(r"^clk_wsp_[0-9A-HJKMNP-TV-Z]{10,}$")
    ulid_ent = re.compile(r"^clk_ent_[0-9A-HJKMNP-TV-Z]{10,}$")
    if not isinstance(workspace_id, str) or not ulid_wsp.match(workspace_id):
        conn = _active_connection()
        _log("get_tasks", conn.get("id") if conn else None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(project_id, str) or not ulid_ent.match(project_id):
        conn = _active_connection()
        _log("get_tasks", conn.get("id") if conn else None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid project_id.")
    if archived is not None and not isinstance(archived, bool):
        conn = _active_connection()
        _log("get_tasks", conn.get("id") if conn else None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid archived; must be boolean.")
    if status is not None and status not in ("active", "archived", "deleted"):
        conn = _active_connection()
        _log("get_tasks", conn.get("id") if conn else None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        conn = _active_connection()
        _log("get_tasks", conn.get("id") if conn else None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid limit; must be integer 1..200.")
    if cursor is not None and not isinstance(cursor, str):
        conn = _active_connection()
        _log("get_tasks", conn.get("id") if conn else None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid cursor.")
    if sort is None:
        sort = "name_asc"
    if sort not in ("name_asc", "name_desc", "created_at_asc", "created_at_desc", "updated_at_asc", "updated_at_desc"):
        conn = _active_connection()
        _log("get_tasks", conn.get("id") if conn else None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort.")

    # --- auth / connection context ---
    conn = _active_connection()
    if not conn:
        _log("get_tasks", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Clockify connection.")
    connection_id = conn.get("id")

    # --- workspace access ---
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id and w.get("connection_id") == connection_id), None)
    if not ws:
        _log("get_tasks", connection_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found or not accessible.")

    entities = _load("workspace_entities.json")
    if not isinstance(entities, list):
        entities = []
    proj = next((e for e in entities if isinstance(e, dict) and e.get("id") == project_id and e.get("workspace_id") == workspace_id and e.get("entity_type") == "project"), None)
    if not proj:
        _log("get_tasks", connection_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found in workspace.")

    # --- cursor decode ---
    start_idx = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if not raw.startswith("clk_cursor:v1:"):
                raise ValueError("bad prefix")
            parts = raw.split(":")
            if len(parts) != 5:
                raise ValueError("bad parts")
            _, _, c_ws, c_pid, c_off = parts
            if c_ws != workspace_id or c_pid != project_id:
                raise ValueError("cursor scope mismatch")
            start_idx = int(c_off)
            if start_idx < 0:
                raise ValueError("neg")
        except Exception:
            _log("get_tasks", connection_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # --- filter tasks ---
    rows = [e for e in entities if isinstance(e, dict) and e.get("workspace_id") == workspace_id and e.get("entity_type") == "task" and e.get("project_id") == project_id]
    if archived is not None:
        rows = [r for r in rows if r.get("archived") is archived]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    # --- sort ---
    def _dt_key(v):
        d = _parse_dt(v)
        if not d:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if d.tzinfo is None:
            d = d.replace(tzinfo=datetime.timezone.utc)
        return d.astimezone(datetime.timezone.utc)

    if sort.startswith("name_"):
        rows.sort(key=lambda r: (str(r.get("name") or "").lower(), str(r.get("id") or "")), reverse=(sort == "name_desc"))
    elif sort.startswith("created_at_"):
        rows.sort(key=lambda r: (_dt_key(r.get("created_at")), str(r.get("id") or "")), reverse=(sort == "created_at_desc"))
    else:
        rows.sort(key=lambda r: (_dt_key(r.get("updated_at")), str(r.get("id") or "")), reverse=(sort == "updated_at_desc"))

    total = len(rows)
    page = rows[start_idx:start_idx + limit]
    next_cursor = None
    has_more = start_idx + limit < total
    if has_more:
        payload = f"clk_cursor:v1:{workspace_id}:{project_id}:{start_idx + limit}"
        next_cursor = base64.urlsafe_b64encode(payload.encode("utf-8")).decode("utf-8").rstrip("=")

    _log("get_tasks", connection_id, "OK")
    return {
        "tasks": [_sanitize_entity(r) for r in page],
        "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}
    }

def create_task(workspace_id, project_id, name, billable=None, archived=None, color=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0487000" if __import__("os").path.isdir("./environment_mix/0487000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(endpoint, connection_id, status_code):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + hashlib.sha256(f"{endpoint}|{connection_id}|{now.isoformat()}|{time.time()}".encode("utf-8")).hexdigest()[:24],
                "endpoint": endpoint,
                "connection_id": connection_id,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _iso(now),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _active_connection():
        conns = _load("clockify_connections.json")
        if not isinstance(conns, list):
            conns = []
        actives = [c for c in conns if isinstance(c, dict) and c.get("provider") == "clockify" and c.get("status") == "active"]
        def k(c):
            ud = _parse_dt(c.get("updated_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (ud, c.get("id") or "")
        actives.sort(key=k, reverse=True)
        return actives[0] if actives else None

    def _new_id(prefix, rows):
        # ULID-like but deterministic enough; avoid collisions by increment suffix.
        base = hashlib.sha256(f"{prefix}|{now.isoformat()}|{time.time()}".encode("utf-8")).hexdigest().upper()
        # map hex -> crockford base32
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        # convert bytes to base32-ish
        b = bytes.fromhex(base[:32])
        acc = 0
        bits = 0
        out = []
        for by in b:
            acc = (acc << 8) | by
            bits += 8
            while bits >= 5:
                bits -= 5
                out.append(alphabet[(acc >> bits) & 31])
        if bits:
            out.append(alphabet[(acc << (5 - bits)) & 31])
        core = "".join(out)[:16]
        candidate = f"{prefix}{core}"
        existing = {r.get("id") for r in rows if isinstance(r, dict)}
        if candidate not in existing:
            return candidate
        i = 1
        while True:
            cand = f"{prefix}{core}{i}"
            if cand not in existing:
                return cand
            i += 1

    def _sanitize_entity(row):
        return dict(row) if isinstance(row, dict) else None

    # --- validation ---
    ulid_wsp = re.compile(r"^clk_wsp_[0-9A-HJKMNP-TV-Z]{10,}$")
    ulid_ent = re.compile(r"^clk_ent_[0-9A-HJKMNP-TV-Z]{10,}$")
    if not isinstance(workspace_id, str) or not ulid_wsp.match(workspace_id):
        conn = _active_connection()
        _log("create_task", conn.get("id") if conn else None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(project_id, str) or not ulid_ent.match(project_id):
        conn = _active_connection()
        _log("create_task", conn.get("id") if conn else None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid project_id.")
    if not isinstance(name, str) or len(name.strip()) < 1:
        conn = _active_connection()
        _log("create_task", conn.get("id") if conn else None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid name; must be non-empty string.")
    if billable is not None and not isinstance(billable, bool):
        conn = _active_connection()
        _log("create_task", conn.get("id") if conn else None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid billable; must be boolean.")
    if archived is not None and not isinstance(archived, bool):
        conn = _active_connection()
        _log("create_task", conn.get("id") if conn else None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid archived; must be boolean.")
    if color is not None and not isinstance(color, str):
        conn = _active_connection()
        _log("create_task", conn.get("id") if conn else None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid color; must be string.")

    conn = _active_connection()
    if not conn:
        _log("create_task", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Clockify connection.")
    connection_id = conn.get("id")

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id and w.get("connection_id") == connection_id), None)
    if not ws:
        _log("create_task", connection_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found or not accessible.")

    entities = _load("workspace_entities.json")
    if not isinstance(entities, list):
        entities = []

    proj = next((e for e in entities if isinstance(e, dict) and e.get("id") == project_id and e.get("workspace_id") == workspace_id and e.get("entity_type") == "project"), None)
    if not proj:
        _log("create_task", connection_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found in workspace.")

    # "Create in Clockify": offline store simulation — treat as success only when connection is active.
    # If connection status active, succeed; if error/revoked we'd already have blocked.
    # Still enforce uniqueness constraint unique(workspace_id, entity_type, external_id) — external_id generated here.
    external_id = "ext_task_" + hashlib.sha256(f"{workspace_id}|{project_id}|{name.strip()}|{now.isoformat()}|{time.time()}".encode("utf-8")).hexdigest()[:20]
    if any(isinstance(e, dict) and e.get("workspace_id") == workspace_id and e.get("entity_type") == "task" and e.get("external_id") == external_id for e in entities):
        _log("create_task", connection_id, "CONFLICT")
        return _err("CONFLICT", "Task external_id conflict; please retry.")

    task_id = _new_id("clk_ent_", entities)
    row = {
        "id": task_id,
        "workspace_id": workspace_id,
        "entity_type": "task",
        "external_id": external_id,
        "name": name.strip(),
        "email": None,
        "project_id": project_id,  # required for tasks
        "client_id": None,
        "billable": billable if billable is not None else None,
        "archived": archived if archived is not None else False,
        "color": color,
        "status": "active" if not (archived is True) else "archived",
        "raw": {"provider": "clockify", "created_via": "create_task"},
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    # validate task->project reference in same workspace (already ensured) and constraint name non-empty
    if row["project_id"] != project_id:
        _log("create_task", connection_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid project reference.")
    # persisted commit
    entities.append(row)
    _save("workspace_entities.json", entities)

    # update connection last_success_at
    conns = _load("clockify_connections.json")
    if isinstance(conns, list):
        for c in conns:
            if isinstance(c, dict) and c.get("id") == connection_id:
                c["last_success_at"] = _iso(now)
                c["updated_at"] = _iso(now)
                break
        _save("clockify_connections.json", conns)

    _log("create_task", connection_id, "OK")
    return {"task": _sanitize_entity(row)}

def get_time_entries(workspace_id, user_id, time_from=None, time_to=None, project_id=None, task_id=None, client_id=None, tag_ids=None, billable=None, status=None, description_search=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0487000" if __import__("os").path.isdir("./environment_mix/0487000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_time_entries"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("__err__", _err("VALIDATION_ERROR", f"{field} must be a date-time string"))
        v = s.strip()
        try:
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(v)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return ("__err__", _err("VALIDATION_ERROR", f"{field} must be a valid RFC3339 date-time"))

    def _ensure_logs_collection():
        candidates = ["request_logs.json", "api_requests.json", "usage_logs.json", "audit_logs.json"]
        for fn in candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _log(connection_id, status_code, error_code=None, extra=None):
        fn = _ensure_logs_collection()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        payload = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{connection_id}|{now.isoformat()}|{time.time()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "connection_id": connection_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now),
        }
        if isinstance(extra, dict):
            payload.update(extra)
        logs.append(payload)
        _save(fn, logs)

    def _enforce_rate_limits(connection_id, kind):
        # best-effort: if config absent, do nothing
        cfg = _load("rate_limits.json")
        if not isinstance(cfg, dict):
            return None
        now = _now_utc()

        logs_fn = _ensure_logs_collection()
        logs = _load(logs_fn)
        if not isinstance(logs, list):
            logs = []

        # limits are enforced per connection_id
        if kind == "clockify_api":
            max_per_min = cfg.get("max_clockify_api_calls_per_minute") or cfg.get("max_api_calls_per_minute")
            if isinstance(max_per_min, int) and max_per_min > 0:
                window_start = now - datetime.timedelta(minutes=1)
                c = 0
                for r in logs:
                    if not isinstance(r, dict): 
                        continue
                    if r.get("connection_id") != connection_id:
                        continue
                    ts = r.get("created_at") or r.get("ts")
                    dt = _parse_dt(ts, "created_at")
                    if isinstance(dt, tuple) and dt and dt[0] == "__err__":
                        continue
                    if isinstance(dt, datetime.datetime) and dt >= window_start:
                        if (r.get("kind") or r.get("limit_kind")) == "clockify_api" or (r.get("endpoint") in ["get_time_entries", "create_time_entry", "start_timer", "stop_timer", "update_time_entry"]):
                            c += 1
                if c >= max_per_min:
                    return _err("RATE_LIMIT", "Clockify API rate limit exceeded. Try again later.")
        elif kind == "reports":
            max_per_hr = cfg.get("max_report_generations_per_hour")
            if isinstance(max_per_hr, int) and max_per_hr > 0:
                window_start = now - datetime.timedelta(hours=1)
                c = 0
                for r in logs:
                    if not isinstance(r, dict):
                        continue
                    if r.get("connection_id") != connection_id:
                        continue
                    ts = r.get("created_at") or r.get("ts")
                    dt = _parse_dt(ts, "created_at")
                    if isinstance(dt, tuple) and dt and dt[0] == "__err__":
                        continue
                    if isinstance(dt, datetime.datetime) and dt >= window_start:
                        if (r.get("kind") or r.get("limit_kind")) == "reports" or (r.get("endpoint") in ["detailed_report", "summary_report"]):
                            c += 1
                if c >= max_per_hr:
                    return _err("QUOTA_EXCEEDED", "Report generation quota exceeded. Try again later.")
        return None

    def _select_active_connection_for_workspace(workspace_id):
        conns = _load("clockify_connections.json")
        if not isinstance(conns, list):
            conns = []
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []

        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if not ws:
            return ("__err__", _err("NOT_FOUND", "Workspace not found."))
        conn_id = ws.get("connection_id")
        if not conn_id:
            return ("__err__", _err("UNAUTHORIZED", "Workspace is not linked to a connection."))

        conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == conn_id and c.get("provider") == "clockify" and c.get("status") == "active"), None)
        if conn:
            return conn

        # fallback search: if workspace record points to inactive connection, still enforce rule: must have some active connection serving this workspace
        # (in practice, connection_id must match; so if it's not active, unauthorized)
        return ("__err__", _err("UNAUTHORIZED", "No active Clockify connection available for this workspace."))

    def _validate_ulid(val, pattern, field):
        if not isinstance(val, str) or not re.match(pattern, val):
            return _err("VALIDATION_ERROR", f"Invalid {field}.")
        return None

    # ---- validate inputs ----
    e = _validate_ulid(workspace_id, r"^clk_wsp_[0-9A-HJKMNP-TV-Z]{10,}$", "workspace_id")
    if e:
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return e

    # NOTE: audit defect showed callers may pass a connection id accidentally. Be tolerant:
    # If user_id is not a clk_ent_..., attempt to resolve to the connection's external user entity within this workspace.
    user_id_is_ent = isinstance(user_id, str) and re.match(r"^clk_ent_[0-9A-HJKMNP-TV-Z]{10,}$", user_id)

    # validate optional entity ids if provided (except tolerate wrong patterns by treating as "no match", not error? spec says validation error; keep strict for these)
    if project_id is not None:
        e = _validate_ulid(project_id, r"^clk_ent_[0-9A-HJKMNP-TV-Z]{10,}$", "project_id")
        if e:
            _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return e
    if task_id is not None:
        e = _validate_ulid(task_id, r"^clk_ent_[0-9A-HJKMNP-TV-Z]{10,}$", "task_id")
        if e:
            _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return e
    if client_id is not None:
        e = _validate_ulid(client_id, r"^clk_ent_[0-9A-HJKMNP-TV-Z]{10,}$", "client_id")
        if e:
            _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return e
    if tag_ids is not None:
        if not isinstance(tag_ids, list):
            _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return _err("VALIDATION_ERROR", "tag_ids must be an array.")
        for tid in tag_ids:
            e = _validate_ulid(tid, r"^clk_ent_[0-9A-HJKMNP-TV-Z]{10,}$", "tag_ids[]")
            if e:
                _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
                return e
    if billable is not None and not isinstance(billable, bool):
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return _err("VALIDATION_ERROR", "billable must be boolean.")
    if status is not None:
        if status not in ["running", "stopped", "deleted"]:
            _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return _err("VALIDATION_ERROR", "Invalid status.")
    if description_search is not None and not isinstance(description_search, str):
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return _err("VALIDATION_ERROR", "description_search must be a string.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sort is None:
        sort = "start_at_desc"
    if sort not in ["start_at_desc", "start_at_asc", "created_at_desc", "created_at_asc", "updated_at_desc", "updated_at_asc"]:
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return _err("VALIDATION_ERROR", "Invalid sort.")

    dt_from = _parse_dt(time_from, "time_from")
    if isinstance(dt_from, tuple) and dt_from and dt_from[0] == "__err__":
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return dt_from[1]
    dt_to = _parse_dt(time_to, "time_to")
    if isinstance(dt_to, tuple) and dt_to and dt_to[0] == "__err__":
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return dt_to[1]
    if isinstance(dt_from, datetime.datetime) and isinstance(dt_to, datetime.datetime) and dt_to < dt_from:
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return _err("VALIDATION_ERROR", "time_to must be greater than or equal to time_from.")

    # ---- auth / connection context ----
    conn = _select_active_connection_for_workspace(workspace_id)
    if isinstance(conn, tuple) and conn and conn[0] == "__err__":
        _log(None, 401, conn[1]["error"]["code"], {"kind": "clockify_api"})
        return conn[1]
    connection_id = conn.get("id")

    # enforce (if enabled)
    lim_err = _enforce_rate_limits(connection_id, "clockify_api")
    if lim_err:
        _log(connection_id, 429, lim_err["error"]["code"], {"kind": "clockify_api"})
        return lim_err

    entities = _load("workspace_entities.json")
    if not isinstance(entities, list):
        entities = []
    time_entries = _load("time_entries.json")
    if not isinstance(time_entries, list):
        time_entries = []

    # resolve tolerant user id
    if user_id_is_ent:
        user_ent = next((e for e in entities if isinstance(e, dict) and e.get("id") == user_id and e.get("workspace_id") == workspace_id and e.get("entity_type") == "user"), None)
        if not user_ent:
            # user_id looks like entity but not found in this workspace -> treat as empty (not error)
            resolved_user_entity_id = user_id
        else:
            resolved_user_entity_id = user_id
    else:
        # try interpret as connection id and map to workspace user by external_user_id
        conns = _load("clockify_connections.json")
        if not isinstance(conns, list):
            conns = []
        conn_row = next((c for c in conns if isinstance(c, dict) and c.get("id") == user_id), None)
        if conn_row and conn_row.get("external_user_id"):
            ext_uid = conn_row.get("external_user_id")
        else:
            # fall back to active connection's external_user_id (authenticated user context)
            ext_uid = conn.get("external_user_id")
        user_ent = next((e for e in entities if isinstance(e, dict) and e.get("workspace_id") == workspace_id and e.get("entity_type") == "user" and e.get("external_id") == ext_uid), None)
        if not user_ent:
            # cannot resolve -> validation error in original code; but to accept valid call patterns, return empty set (read)
            resolved_user_entity_id = "__unresolvable__"
        else:
            resolved_user_entity_id = user_ent.get("id")

    # validate referenced filter entity existence/types if present (but reads should not error if filters point to non-existent? keep validation strict only for tags because business rule mentions rejection on invalid tag ids for mutations; for reads, treat as no matches)
    def _ent_by_id(eid):
        return next((r for r in entities if isinstance(r, dict) and r.get("id") == eid and r.get("workspace_id") == workspace_id), None)

    if project_id is not None:
        pr = _ent_by_id(project_id)
        if pr and pr.get("entity_type") != "project":
            _log(connection_id, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return _err("VALIDATION_ERROR", "project_id must reference a project entity in this workspace.")
    if task_id is not None:
        tr = _ent_by_id(task_id)
        if tr and tr.get("entity_type") != "task":
            _log(connection_id, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return _err("VALIDATION_ERROR", "task_id must reference a task entity in this workspace.")
    if client_id is not None:
        cr = _ent_by_id(client_id)
        if cr and cr.get("entity_type") != "client":
            _log(connection_id, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return _err("VALIDATION_ERROR", "client_id must reference a client entity in this workspace.")

    # ---- filter ----
    rows = [r for r in time_entries if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("user_entity_id") == resolved_user_entity_id]

    # time window filter: include if overlaps [time_from, time_to)
    def _row_dt(v):
        dt = _parse_dt(v, "dt")
        if isinstance(dt, tuple):
            return None
        return dt

    if isinstance(dt_from, datetime.datetime) or isinstance(dt_to, datetime.datetime):
        f = dt_from
        t = dt_to
        out = []
        for r in rows:
            sdt = _row_dt(r.get("start_at"))
            edt = _row_dt(r.get("end_at"))
            # running: edt is None; treat as now for overlap checks
            edt_eff = edt if isinstance(edt, datetime.datetime) else _now_utc()
            sdt_eff = sdt if isinstance(sdt, datetime.datetime) else None
            if sdt_eff is None:
                continue
            if isinstance(f, datetime.datetime) and edt_eff < f:
                continue
            if isinstance(t, datetime.datetime) and sdt_eff >= t:
                continue
            out.append(r)
        rows = out

    if project_id is not None:
        rows = [r for r in rows if r.get("project_entity_id") == project_id]
    if task_id is not None:
        rows = [r for r in rows if r.get("task_entity_id") == task_id]
    if client_id is not None:
        rows = [r for r in rows if r.get("client_entity_id") == client_id]
    if tag_ids is not None and len(tag_ids) > 0:
        want = set(tag_ids)
        def _has_any(r):
            tids = r.get("tag_entity_ids")
            if not isinstance(tids, list):
                return False
            return any(t in want for t in tids)
        rows = [r for r in rows if _has_any(r)]
    if billable is not None:
        rows = [r for r in rows if r.get("billable") is billable]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if description_search is not None and description_search != "":
        needle = description_search.lower()
        def _match_desc(r):
            d = r.get("description")
            if not isinstance(d, str):
                return False
            return needle in d.lower()
        rows = [r for r in rows if _match_desc(r)]

    # ---- sort ----
    def _key_dt(val):
        dt = _row_dt(val)
        if isinstance(dt, datetime.datetime):
            return dt
        return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    if sort == "start_at_desc":
        rows.sort(key=lambda r: (_key_dt(r.get("start_at")), r.get("id") or ""), reverse=True)
    elif sort == "start_at_asc":
        rows.sort(key=lambda r: (_key_dt(r.get("start_at")), r.get("id") or ""))
    elif sort == "created_at_desc":
        rows.sort(key=lambda r: (_key_dt(r.get("created_at")), r.get("id") or ""), reverse=True)
    elif sort == "created_at_asc":
        rows.sort(key=lambda r: (_key_dt(r.get("created_at")), r.get("id") or ""))
    elif sort == "updated_at_desc":
        rows.sort(key=lambda r: (_key_dt(r.get("updated_at")), r.get("id") or ""), reverse=True)
    elif sort == "updated_at_asc":
        rows.sort(key=lambda r: (_key_dt(r.get("updated_at")), r.get("id") or ""))

    # ---- cursor pagination (opaque) ----
    start_index = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if isinstance(payload, dict) and payload.get("v") == 1:
                if payload.get("workspace_id") == workspace_id and payload.get("user_entity_id") == resolved_user_entity_id and payload.get("sort") == sort:
                    after_id = payload.get("after_id")
                    if isinstance(after_id, str):
                        for i, r in enumerate(rows):
                            if r.get("id") == after_id:
                                start_index = i + 1
                                break
        except Exception:
            # invalid cursor => validation error (matches typical API behaviour)
            _log(connection_id, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    page = rows[start_index:start_index + limit]
    has_more = start_index + limit < len(rows)
    next_cursor = None
    if has_more and page:
        payload = {"v": 1, "workspace_id": workspace_id, "user_entity_id": resolved_user_entity_id, "sort": sort, "after_id": page[-1].get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    _log(connection_id, 200, None, {"kind": "clockify_api"})
    return {
        "time_entries": page,
        "total": len(rows),
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort": sort,
    }

def create_time_entry(workspace_id, user_id, description=None, billable=None, project_id=None, task_id=None, client_id=None, tag_ids=None, start_at=None, end_at=None, **_extra):
    import json, os, datetime, time, re, random, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0487000" if __import__("os").path.isdir("./environment_mix/0487000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_time_entry"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("__err__", _err("VALIDATION_ERROR", f"{field} must be a date-time string"))
        v = s.strip()
        try:
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(v)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return ("__err__", _err("VALIDATION_ERROR", f"{field} must be a valid RFC3339 date-time"))

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_ulid(prefix):
        ms = int(time.time() * 1000)
        rnd = random.getrandbits(80)
        val = (ms << 80) | rnd
        chars = []
        for _ in range(26):
            chars.append(_B32[val & 31])
            val >>= 5
        return prefix + "".join(reversed(chars))

    def _ensure_logs_collection():
        candidates = ["request_logs.json", "api_requests.json", "usage_logs.json", "audit_logs.json"]
        for fn in candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _log(connection_id, status_code, error_code=None, extra=None):
        fn = _ensure_logs_collection()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{connection_id}|{now.isoformat()}|{time.time()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "connection_id": connection_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(fn, logs)

    def _enforce_rate_limits(connection_id):
        cfg = _load("rate_limits.json")
        if not isinstance(cfg, dict):
            return None
        max_per_min = cfg.get("max_clockify_api_calls_per_minute") or cfg.get("max_api_calls_per_minute")
        if not (isinstance(max_per_min, int) and max_per_min > 0):
            return None
        logs_fn = _ensure_logs_collection()
        logs = _load(logs_fn)
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        window_start = now - datetime.timedelta(minutes=1)
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("connection_id") != connection_id:
                continue
            ts = r.get("created_at") or r.get("ts")
            dt = _parse_dt(ts, "created_at")
            if isinstance(dt, tuple):
                continue
            if isinstance(dt, datetime.datetime) and dt >= window_start:
                if (r.get("kind") or r.get("limit_kind")) == "clockify_api" or (r.get("endpoint") in ["get_time_entries", "create_time_entry", "start_timer", "stop_timer", "update_time_entry"]):
                    c += 1
        if c >= max_per_min:
            return _err("RATE_LIMIT", "Clockify API rate limit exceeded. Try again later.")
        return None

    def _select_active_connection_for_workspace(workspace_id):
        conns = _load("clockify_connections.json")
        if not isinstance(conns, list):
            conns = []
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if not ws:
            return ("__err__", _err("NOT_FOUND", "Workspace not found."))
        cid = ws.get("connection_id")
        if not cid:
            return ("__err__", _err("UNAUTHORIZED", "Workspace is not linked to a connection."))
        conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == cid and c.get("provider") == "clockify" and c.get("status") == "active"), None)
        if not conn:
            return ("__err__", _err("UNAUTHORIZED", "No active Clockify connection available for this workspace."))
        return conn

    def _validate_ulid(val, pattern, field):
        if not isinstance(val, str) or not re.match(pattern, val):
            return _err("VALIDATION_ERROR", f"Invalid {field}.")
        return None

    # ---- validate ----
    e = _validate_ulid(workspace_id, r"^clk_wsp_[0-9A-HJKMNP-TV-Z]{10,}$", "workspace_id")
    if e:
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return e

    # tolerate user_id being a connection id (observed in audit); resolve later
    user_id_is_ent = isinstance(user_id, str) and re.match(r"^clk_ent_[0-9A-HJKMNP-TV-Z]{10,}$", user_id)

    if description is not None and not isinstance(description, str):
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return _err("VALIDATION_ERROR", "description must be a string.")
    if billable is not None and not isinstance(billable, bool):
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return _err("VALIDATION_ERROR", "billable must be boolean.")
    if project_id is not None:
        e = _validate_ulid(project_id, r"^clk_ent_[0-9A-HJKMNP-TV-Z]{10,}$", "project_id")
        if e:
            _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return e
    if task_id is not None:
        e = _validate_ulid(task_id, r"^clk_ent_[0-9A-HJKMNP-TV-Z]{10,}$", "task_id")
        if e:
            _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return e
    if client_id is not None:
        e = _validate_ulid(client_id, r"^clk_ent_[0-9A-HJKMNP-TV-Z]{10,}$", "client_id")
        if e:
            _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return e
    if tag_ids is not None:
        if not isinstance(tag_ids, list):
            _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return _err("VALIDATION_ERROR", "tag_ids must be an array.")
        for tid in tag_ids:
            e = _validate_ulid(tid, r"^clk_ent_[0-9A-HJKMNP-TV-Z]{10,}$", "tag_ids[]")
            if e:
                _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
                return e
    if start_at is None:
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return _err("VALIDATION_ERROR", "start_at is required.")
    dt_start = _parse_dt(start_at, "start_at")
    if isinstance(dt_start, tuple):
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return dt_start[1]
    dt_end = _parse_dt(end_at, "end_at")
    if isinstance(dt_end, tuple):
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return dt_end[1]
    if isinstance(dt_end, datetime.datetime) and dt_end < dt_start:
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return _err("VALIDATION_ERROR", "end_at must be greater than or equal to start_at.")

    # ---- auth/context ----
    conn = _select_active_connection_for_workspace(workspace_id)
    if isinstance(conn, tuple) and conn and conn[0] == "__err__":
        _log(None, 401, conn[1]["error"]["code"], {"kind": "clockify_api"})
        return conn[1]
    connection_id = conn.get("id")

    lim_err = _enforce_rate_limits(connection_id)
    if lim_err:
        _log(connection_id, 429, lim_err["error"]["code"], {"kind": "clockify_api"})
        return lim_err

    entities = _load("workspace_entities.json")
    if not isinstance(entities, list):
        entities = []
    time_entries = _load("time_entries.json")
    if not isinstance(time_entries, list):
        time_entries = []

    # resolve user_entity_id
    if user_id_is_ent:
        user_ent = next((e for e in entities if isinstance(e, dict) and e.get("id") == user_id and e.get("workspace_id") == workspace_id and e.get("entity_type") == "user"), None)
        if not user_ent:
            _log(connection_id, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return _err("VALIDATION_ERROR", "user_id must reference a user entity in this workspace.")
        user_entity_id = user_id
    else:
        # treat user_id as connection id or garbage; map to authenticated connection's external_user_id
        ext_uid = conn.get("external_user_id")
        conns = _load("clockify_connections.json")
        if isinstance(conns, list):
            c2 = next((c for c in conns if isinstance(c, dict) and c.get("id") == user_id and c.get("external_user_id")), None)
            if c2:
                ext_uid = c2.get("external_user_id")
        user_ent = next((e for e in entities if isinstance(e, dict) and e.get("workspace_id") == workspace_id and e.get("entity_type") == "user" and e.get("external_id") == ext_uid), None)
        if not user_ent:
            _log(connection_id, 401, "UNAUTHORIZED", {"kind": "clockify_api"})
            return _err("UNAUTHORIZED", "No user mapping available in this workspace for the active connection.")
        user_entity_id = user_ent.get("id")

    # validate entity references and relationships
    def _ent(eid):
        return next((r for r in entities if isinstance(r, dict) and r.get("id") == eid and r.get("workspace_id") == workspace_id), None)

    if project_id is not None:
        pr = _ent(project_id)
        if not pr or pr.get("entity_type") != "project":
            _log(connection_id, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return _err("VALIDATION_ERROR", "project_id must reference a project entity in this workspace.")
    if client_id is not None:
        cr = _ent(client_id)
        if not cr or cr.get("entity_type") != "client":
            _log(connection_id, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return _err("VALIDATION_ERROR", "client_id must reference a client entity in this workspace.")
    if task_id is not None:
        tr = _ent(task_id)
        if not tr or tr.get("entity_type") != "task":
            _log(connection_id, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return _err("VALIDATION_ERROR", "task_id must reference a task entity in this workspace.")
        if project_id is None:
            _log(connection_id, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return _err("VALIDATION_ERROR", "A time entry may reference task_id only if it also references project_id.")
        if tr.get("project_id") != project_id:
            _log(connection_id, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return _err("VALIDATION_ERROR", "task_id must belong to the provided project_id.")
    if tag_ids is not None:
        for tid in tag_ids:
            tg = _ent(tid)
            if not tg or tg.get("entity_type") != "tag":
                _log(connection_id, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
                return _err("VALIDATION_ERROR", "Tags must reference 'tag' entities in the same workspace.")

    # enforce at most 1 running time entry per (workspace_id, user_entity_id)
    is_running = dt_end is None
    if is_running:
        running = [r for r in time_entries if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("user_entity_id") == user_entity_id and r.get("status") == "running"]
        if running:
            # consistent choice: stop existing running entry first
            now = _now_utc()
            for r in running:
                sdt = _parse_dt(r.get("start_at"), "start_at")
                if isinstance(sdt, tuple):
                    sdt = None
                if not isinstance(sdt, datetime.datetime):
                    sdt = now
                r["end_at"] = _iso(now)
                r["duration_seconds"] = int(max(0, (now - sdt).total_seconds()))
                r["status"] = "stopped"
                r["updated_at"] = _iso(now)

    # create entry
    now = _now_utc()
    new_id = _new_ulid("clk_te_")
    row = {
        "id": new_id,
        "workspace_id": workspace_id,
        "user_entity_id": user_entity_id,
        "external_time_entry_id": None,
        "project_entity_id": project_id,
        "task_entity_id": task_id,
        "client_entity_id": client_id,
        "description": description,
        "billable": bool(billable) if billable is not None else False,
        "start_at": _iso(dt_start),
        "end_at": _iso(dt_end) if isinstance(dt_end, datetime.datetime) else None,
        "duration_seconds": None,
        "tag_entity_ids": list(tag_ids) if isinstance(tag_ids, list) else None,
        "status": "running" if is_running else "stopped",
        "source": "api_create",
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    if row["status"] == "stopped":
        row["duration_seconds"] = int(max(0, (dt_end - dt_start).total_seconds())) if isinstance(dt_end, datetime.datetime) else 0

    time_entries.append(row)
    _save("time_entries.json", time_entries)

    # connection success markers
    conns = _load("clockify_connections.json")
    if isinstance(conns, list):
        for c in conns:
            if isinstance(c, dict) and c.get("id") == connection_id:
                c["last_success_at"] = _iso(now)
                c["last_error_at"] = None
                c["last_error_message"] = None
                c["updated_at"] = _iso(now)
                break
        _save("clockify_connections.json", conns)

    _log(connection_id, 201, None, {"kind": "clockify_api"})
    return {"time_entry": row}

def start_timer(workspace_id, user_id, description=None, billable=None, project_id=None, task_id=None, client_id=None, tag_ids=None, start_at=None, **_extra):
    import json, os, datetime, time, re, random, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0487000" if __import__("os").path.isdir("./environment_mix/0487000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "start_timer"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("__err__", _err("VALIDATION_ERROR", f"{field} must be a date-time string"))
        try:
            v = s.strip()
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(v)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return ("__err__", _err("VALIDATION_ERROR", f"{field} must be a valid RFC3339 date-time"))

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_ulid(prefix):
        ms = int(time.time() * 1000)
        rnd = random.getrandbits(80)
        val = (ms << 80) | rnd
        chars = []
        for _ in range(26):
            chars.append(_B32[val & 31])
            val >>= 5
        return prefix + "".join(reversed(chars))

    def _ensure_logs_collection():
        candidates = ["request_logs.json", "api_requests.json", "usage_logs.json", "audit_logs.json"]
        for fn in candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _log(connection_id, status_code, error_code=None, extra=None):
        fn = _ensure_logs_collection()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{connection_id}|{now.isoformat()}|{time.time()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "connection_id": connection_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(fn, logs)

    def _enforce_rate_limits(connection_id):
        cfg = _load("rate_limits.json")
        if not isinstance(cfg, dict):
            return None
        max_per_min = cfg.get("max_clockify_api_calls_per_minute") or cfg.get("max_api_calls_per_minute")
        if not (isinstance(max_per_min, int) and max_per_min > 0):
            return None
        logs_fn = _ensure_logs_collection()
        logs = _load(logs_fn)
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        window_start = now - datetime.timedelta(minutes=1)
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("connection_id") != connection_id:
                continue
            ts = r.get("created_at") or r.get("ts")
            dt = _parse_dt(ts, "created_at")
            if isinstance(dt, tuple):
                continue
            if isinstance(dt, datetime.datetime) and dt >= window_start:
                if (r.get("kind") or r.get("limit_kind")) == "clockify_api" or (r.get("endpoint") in ["get_time_entries", "create_time_entry", "start_timer", "stop_timer", "update_time_entry"]):
                    c += 1
        if c >= max_per_min:
            return _err("RATE_LIMIT", "Clockify API rate limit exceeded. Try again later.")
        return None

    def _select_active_connection_for_workspace(workspace_id):
        conns = _load("clockify_connections.json")
        if not isinstance(conns, list):
            conns = []
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if not ws:
            return ("__err__", _err("NOT_FOUND", "Workspace not found."))
        cid = ws.get("connection_id")
        if not cid:
            return ("__err__", _err("UNAUTHORIZED", "Workspace is not linked to a connection."))
        conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == cid and c.get("provider") == "clockify" and c.get("status") == "active"), None)
        if not conn:
            return ("__err__", _err("UNAUTHORIZED", "No active Clockify connection available for this workspace."))
        return conn

    def _validate_ulid(val, pattern, field):
        if not isinstance(val, str) or not re.match(pattern, val):
            return _err("VALIDATION_ERROR", f"Invalid {field}.")
        return None

    # validate
    e = _validate_ulid(workspace_id, r"^clk_wsp_[0-9A-HJKMNP-TV-Z]{10,}$", "workspace_id")
    if e:
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return e

    user_id_is_ent = isinstance(user_id, str) and re.match(r"^clk_ent_[0-9A-HJKMNP-TV-Z]{10,}$", user_id)

    if description is not None and not isinstance(description, str):
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return _err("VALIDATION_ERROR", "description must be a string.")
    if billable is not None and not isinstance(billable, bool):
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return _err("VALIDATION_ERROR", "billable must be boolean.")
    if project_id is not None:
        e = _validate_ulid(project_id, r"^clk_ent_[0-9A-HJKMNP-TV-Z]{10,}$", "project_id")
        if e:
            _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return e
    if task_id is not None:
        e = _validate_ulid(task_id, r"^clk_ent_[0-9A-HJKMNP-TV-Z]{10,}$", "task_id")
        if e:
            _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return e
    if client_id is not None:
        e = _validate_ulid(client_id, r"^clk_ent_[0-9A-HJKMNP-TV-Z]{10,}$", "client_id")
        if e:
            _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return e
    if tag_ids is not None:
        if not isinstance(tag_ids, list):
            _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return _err("VALIDATION_ERROR", "tag_ids must be an array.")
        for tid in tag_ids:
            e = _validate_ulid(tid, r"^clk_ent_[0-9A-HJKMNP-TV-Z]{10,}$", "tag_ids[]")
            if e:
                _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
                return e
    dt_start = _parse_dt(start_at, "start_at")
    if isinstance(dt_start, tuple):
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return dt_start[1]
    if dt_start is None:
        dt_start = _now_utc()

    # context
    conn = _select_active_connection_for_workspace(workspace_id)
    if isinstance(conn, tuple) and conn and conn[0] == "__err__":
        _log(None, 401, conn[1]["error"]["code"], {"kind": "clockify_api"})
        return conn[1]
    connection_id = conn.get("id")

    lim_err = _enforce_rate_limits(connection_id)
    if lim_err:
        _log(connection_id, 429, lim_err["error"]["code"], {"kind": "clockify_api"})
        return lim_err

    entities = _load("workspace_entities.json")
    if not isinstance(entities, list):
        entities = []
    time_entries = _load("time_entries.json")
    if not isinstance(time_entries, list):
        time_entries = []

    # resolve user
    if user_id_is_ent:
        user_ent = next((e for e in entities if isinstance(e, dict) and e.get("id") == user_id and e.get("workspace_id") == workspace_id and e.get("entity_type") == "user"), None)
        if not user_ent:
            _log(connection_id, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return _err("VALIDATION_ERROR", "user_id must reference a user entity in this workspace.")
        user_entity_id = user_id
    else:
        ext_uid = conn.get("external_user_id")
        conns = _load("clockify_connections.json")
        if isinstance(conns, list):
            c2 = next((c for c in conns if isinstance(c, dict) and c.get("id") == user_id and c.get("external_user_id")), None)
            if c2:
                ext_uid = c2.get("external_user_id")
        user_ent = next((e for e in entities if isinstance(e, dict) and e.get("workspace_id") == workspace_id and e.get("entity_type") == "user" and e.get("external_id") == ext_uid), None)
        if not user_ent:
            _log(connection_id, 401, "UNAUTHORIZED", {"kind": "clockify_api"})
            return _err("UNAUTHORIZED", "No user mapping available in this workspace for the active connection.")
        user_entity_id = user_ent.get("id")

    def _ent(eid):
        return next((r for r in entities if isinstance(r, dict) and r.get("id") == eid and r.get("workspace_id") == workspace_id), None)

    if project_id is not None:
        pr = _ent(project_id)
        if not pr or pr.get("entity_type") != "project":
            _log(connection_id, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return _err("VALIDATION_ERROR", "project_id must reference a project entity in this workspace.")
    if client_id is not None:
        cr = _ent(client_id)
        if not cr or cr.get("entity_type") != "client":
            _log(connection_id, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return _err("VALIDATION_ERROR", "client_id must reference a client entity in this workspace.")
    if task_id is not None:
        tr = _ent(task_id)
        if not tr or tr.get("entity_type") != "task":
            _log(connection_id, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return _err("VALIDATION_ERROR", "task_id must reference a task entity in this workspace.")
        if project_id is None:
            _log(connection_id, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return _err("VALIDATION_ERROR", "A time entry may reference task_id only if it also references project_id.")
        if tr.get("project_id") != project_id:
            _log(connection_id, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return _err("VALIDATION_ERROR", "task_id must belong to the provided project_id.")
    if tag_ids is not None:
        for tid in tag_ids:
