                _log(connection_id, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
                return _err("VALIDATION_ERROR", "Tags must reference 'tag' entities in the same workspace.")

    # enforce single running timer: stop existing running entry first
    now = _now_utc()
    running = [r for r in time_entries if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("user_entity_id") == user_entity_id and r.get("status") == "running"]
    if running:
        for r in running:
            sdt = _parse_dt(r.get("start_at"), "start_at")
            if isinstance(sdt, tuple):
                sdt = None
            if not isinstance(sdt, datetime.datetime):
                sdt = now
            r["end_at"] = _iso(now)
            r["duration_seconds"] = int(max(0, (now - sdt).total_seconds()))
            r["status"] = "stopped"
            r["updated_at"] = _iso(now)

    # create running entry
    new_id = _new_ulid("clk_te_")
    row = {
        "id": new_id,
        "workspace_id": workspace_id,
        "user_entity_id": user_entity_id,
        "external_time_entry_id": None,
        "project_entity_id": project_id,
        "task_entity_id": task_id,
        "client_entity_id": client_id,
        "description": description,
        "billable": bool(billable) if billable is not None else False,
        "start_at": _iso(dt_start),
        "end_at": None,
        "duration_seconds": None,
        "tag_entity_ids": list(tag_ids) if isinstance(tag_ids, list) else None,
        "status": "running",
        "source": "api_timer",
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    time_entries.append(row)
    _save("time_entries.json", time_entries)

    # connection success markers
    conns = _load("clockify_connections.json")
    if isinstance(conns, list):
        for c in conns:
            if isinstance(c, dict) and c.get("id") == connection_id:
                c["last_success_at"] = _iso(now)
                c["last_error_at"] = None
                c["last_error_message"] = None
                c["updated_at"] = _iso(now)
                break
        _save("clockify_connections.json", conns)

    _log(connection_id, 201, None, {"kind": "clockify_api"})
    return {"time_entry": row}

def stop_timer(workspace_id, user_id, end_at=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0487000" if __import__("os").path.isdir("./environment_mix/0487000") else "/app/database")
    def _load(n):
