    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("__err__", _err("VALIDATION_ERROR", f"{field} must be a date-time string"))
        try:
            v = s.strip()
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(v)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return ("__err__", _err("VALIDATION_ERROR", f"{field} must be a valid RFC3339 date-time"))

    def _ensure_logs_collection():
        candidates = ["request_logs.json", "api_requests.json", "usage_logs.json", "audit_logs.json"]
        for fn in candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _log(connection_id, status_code, error_code=None, extra=None):
        fn = _ensure_logs_collection()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{connection_id}|{now.isoformat()}|{time.time()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "connection_id": connection_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(fn, logs)

    def _enforce_rate_limits(connection_id):
        cfg = _load("rate_limits.json")
        if not isinstance(cfg, dict):
            return None
        max_per_min = cfg.get("max_clockify_api_calls_per_minute") or cfg.get("max_api_calls_per_minute")
        if not (isinstance(max_per_min, int) and max_per_min > 0):
            return None
        logs_fn = _ensure_logs_collection()
        logs = _load(logs_fn)
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        window_start = now - datetime.timedelta(minutes=1)
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("connection_id") != connection_id:
                continue
            ts = r.get("created_at") or r.get("ts")
            dt = _parse_dt(ts, "created_at")
            if isinstance(dt, tuple):
                continue
            if isinstance(dt, datetime.datetime) and dt >= window_start:
                if (r.get("kind") or r.get("limit_kind")) == "clockify_api" or (r.get("endpoint") in ["get_time_entries", "create_time_entry", "start_timer", "stop_timer", "update_time_entry"]):
                    c += 1
        if c >= max_per_min:
            return _err("RATE_LIMIT", "Clockify API rate limit exceeded. Try again later.")
        return None

    def _select_active_connection_for_workspace(workspace_id):
        conns = _load("clockify_connections.json")
        if not isinstance(conns, list):
            conns = []
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if not ws:
            return ("__err__", _err("NOT_FOUND", "Workspace not found."))
        cid = ws.get("connection_id")
        if not cid:
            return ("__err__", _err("UNAUTHORIZED", "Workspace is not linked to a connection."))
        conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == cid and c.get("provider") == "clockify" and c.get("status") == "active"), None)
        if not conn:
            return ("__err__", _err("UNAUTHORIZED", "No active Clockify connection available for this workspace."))
        return conn

    # validate
    if not isinstance(workspace_id, str) or not re.match(r"^clk_wsp_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    user_id_is_ent = isinstance(user_id, str) and re.match(r"^clk_ent_[0-9A-HJKMNP-TV-Z]{10,}$", user_id)

    dt_end = _parse_dt(end_at, "end_at")
    if isinstance(dt_end, tuple):
        _log(None, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return dt_end[1]
    if dt_end is None:
        dt_end = _now_utc()

    # context
    conn = _select_active_connection_for_workspace(workspace_id)
    if isinstance(conn, tuple) and conn and conn[0] == "__err__":
        _log(None, 401, conn[1]["error"]["code"], {"kind": "clockify_api"})
        return conn[1]
    connection_id = conn.get("id")

    lim_err = _enforce_rate_limits(connection_id)
    if lim_err:
        _log(connection_id, 429, lim_err["error"]["code"], {"kind": "clockify_api"})
        return lim_err

    entities = _load("workspace_entities.json")
    if not isinstance(entities, list):
        entities = []
    time_entries = _load("time_entries.json")
    if not isinstance(time_entries, list):
        time_entries = []

    # resolve user
    if user_id_is_ent:
        user_ent = next((e for e in entities if isinstance(e, dict) and e.get("id") == user_id and e.get("workspace_id") == workspace_id and e.get("entity_type") == "user"), None)
        if not user_ent:
            _log(connection_id, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
            return _err("VALIDATION_ERROR", "user_id must reference a user entity in this workspace.")
        user_entity_id = user_id
    else:
        ext_uid = conn.get("external_user_id")
        conns = _load("clockify_connections.json")
        if isinstance(conns, list):
            c2 = next((c for c in conns if isinstance(c, dict) and c.get("id") == user_id and c.get("external_user_id")), None)
            if c2:
                ext_uid = c2.get("external_user_id")
        user_ent = next((e for e in entities if isinstance(e, dict) and e.get("workspace_id") == workspace_id and e.get("entity_type") == "user" and e.get("external_id") == ext_uid), None)
        if not user_ent:
            _log(connection_id, 401, "UNAUTHORIZED", {"kind": "clockify_api"})
            return _err("UNAUTHORIZED", "No user mapping available in this workspace for the active connection.")
        user_entity_id = user_ent.get("id")

    running = [r for r in time_entries if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("user_entity_id") == user_entity_id and r.get("status") == "running"]
    if not running:
        # implementation choice: return NOT_FOUND (no-op but explicit), do not create anything
        _log(connection_id, 404, "NOT_FOUND", {"kind": "clockify_api"})
        return _err("NOT_FOUND", "No running timer found for this user in this workspace.")

    # there should be at most 1; stop the first deterministically by earliest created_at/id
    def _key(r):
        return (r.get("created_at") or "", r.get("id") or "")
    running.sort(key=_key)
    row = running[0]

    dt_start = _parse_dt(row.get("start_at"), "start_at")
    if isinstance(dt_start, tuple) or not isinstance(dt_start, datetime.datetime):
        dt_start = dt_end  # avoid crashing, duration becomes 0

    if dt_end < dt_start:
        _log(connection_id, 400, "VALIDATION_ERROR", {"kind": "clockify_api"})
        return _err("VALIDATION_ERROR", "end_at must be greater than or equal to the entry start_at.")

    now = _now_utc()
    row["end_at"] = _iso(dt_end)
    row["duration_seconds"] = int(max(0, (dt_end - dt_start).total_seconds()))
    row["status"] = "stopped"
    row["updated_at"] = _iso(now)

    _save("time_entries.json", time_entries)

    conns = _load("clockify_connections.json")
    if isinstance(conns, list):
        for c in conns:
            if isinstance(c, dict) and c.get("id") == connection_id:
                c["last_success_at"] = _iso(now)
                c["last_error_at"] = None
                c["last_error_message"] = None
                c["updated_at"] = _iso(now)
                break
        _save("clockify_connections.json", conns)

    _log(connection_id, 200, None, {"kind": "clockify_api"})
    return {"time_entry": row}

def get_tags(workspace_id, archived=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, re, random, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0487000" if __import__("os").path.isdir("./environment_mix/0487000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _pick_active_connection(conns):
        act = [c for c in conns if c.get("provider") == "clockify" and c.get("status") == "active"]
        if not act:
            return None
        act.sort(key=lambda r: (r.get("updated_at") or "", r.get("created_at") or "", r.get("id") or ""))
        return act[-1]

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_ulid(prefix):
        ms = int(time.time() * 1000)
        rnd = random.getrandbits(80)
        val = (ms << 80) | rnd
        chars = []
        for _ in range(26):
            chars.append(_B32[val & 31])
            val >>= 5
        return prefix + "".join(reversed(chars))

    def _ensure_logs_collection():
        candidates = ["request_logs.json", "audit_logs.json", "usage_logs.json", "api_requests.json"]
        for fn in candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _log_and_enforce(connection_id, endpoint, status, start_ts, extra=None):
        logs_file = _ensure_logs_collection()
        logs = _load(logs_file)
        now = _now()
        latency_ms = int((time.time() - start_ts) * 1000)

        limit_per_min = 60
        window_start = now - datetime.timedelta(minutes=1)
        recent = 0
        for r in logs:
            if r.get("connection_id") != connection_id:
                continue
            ts = r.get("timestamp")
            if not ts or not isinstance(ts, str):
                continue
            try:
                vv = ts[:-1] + "+00:00" if ts.endswith("Z") else ts
                dt = datetime.datetime.fromisoformat(vv)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
                if dt >= window_start:
                    recent += 1
            except ValueError:
                continue

        if recent >= limit_per_min:
            row = {
                "id": _new_ulid("clk_req_"),
                "timestamp": _iso(now),
                "endpoint": endpoint,
                "connection_id": connection_id,
                "status": "RATE_LIMIT",
                "http_status": 429,
                "latency_ms": latency_ms,
            }
            if extra:
                row.update(extra)
            logs.append(row)
            _save(logs_file, logs)
            return ("__err__", _err("RATE_LIMIT", "Too many requests for this connection; retry later", limit_per_min=limit_per_min))

        row = {
            "id": _new_ulid("clk_req_"),
            "timestamp": _iso(now),
            "endpoint": endpoint,
            "connection_id": connection_id,
            "status": status,
            "http_status": 200 if status == "OK" else 400,
            "latency_ms": latency_ms,
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save(logs_file, logs)
        return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return ("__err__", _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided"))
        try:
            pad = "=" * ((4 - (len(s) % 4)) % 4)
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or "offset" not in obj:
                return ("__err__", _err("VALIDATION_ERROR", "cursor is invalid"))
            if not isinstance(obj["offset"], int) or obj["offset"] < 0:
                return ("__err__", _err("VALIDATION_ERROR", "cursor is invalid"))
            return obj
        except Exception:
            return ("__err__", _err("VALIDATION_ERROR", "cursor is invalid"))

    t0 = time.time()

    if not isinstance(workspace_id, str) or not re.match(r"^clk_wsp_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
        conns = _load("clockify_connections.json")
        conn = _pick_active_connection(conns)
        if conn:
            _log_and_enforce(conn.get("id"), "get_tags", "VALIDATION_ERROR", t0)
        return _err("VALIDATION_ERROR", "workspace_id must be a valid clk_wsp_ ULID")

    if archived is not None and not isinstance(archived, bool):
        conns = _load("clockify_connections.json")
        conn = _pick_active_connection(conns)
        if conn:
            _log_and_enforce(conn.get("id"), "get_tags", "VALIDATION_ERROR", t0)
        return _err("VALIDATION_ERROR", "archived must be boolean")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            conns = _load("clockify_connections.json")
            conn = _pick_active_connection(conns)
            if conn:
                _log_and_enforce(conn.get("id"), "get_tags", "VALIDATION_ERROR", t0)
            return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        conns = _load("clockify_connections.json")
        conn = _pick_active_connection(conns)
        if conn:
            _log_and_enforce(conn.get("id"), "get_tags", "VALIDATION_ERROR", t0)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    if sort is None:
        sort = "name_asc"
    if not isinstance(sort, str) or sort not in ("name_asc", "name_desc", "created_at_asc", "created_at_desc", "updated_at_asc", "updated_at_desc"):
        conns = _load("clockify_connections.json")
        conn = _pick_active_connection(conns)
        if conn:
            _log_and_enforce(conn.get("id"), "get_tags", "VALIDATION_ERROR", t0)
        return _err("VALIDATION_ERROR", "sort must be a supported value")

    cur = _decode_cursor(cursor)
    if isinstance(cur, tuple) and cur and cur[0] == "__err__":
        conns = _load("clockify_connections.json")
        conn = _pick_active_connection(conns)
        if conn:
            _log_and_enforce(conn.get("id"), "get_tags", "VALIDATION_ERROR", t0)
        return cur[1]
    offset = cur["offset"] if isinstance(cur, dict) else 0

    conns = _load("clockify_connections.json")
    conn = _pick_active_connection(conns)
    if not conn:
        return _err("UNAUTHORIZED", "No active Clockify connection available")

    limited = _log_and_enforce(conn.get("id"), "get_tags", "PENDING", t0)
    if isinstance(limited, tuple) and limited[0] == "__err__":
        return limited[1]

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id and w.get("connection_id") == conn.get("id")), None)
    if not ws:
        _log_and_enforce(conn.get("id"), "get_tags", "NOT_FOUND", t0)
        return _err("NOT_FOUND", "Workspace not found for active connection", workspace_id=workspace_id)

    entities = _load("workspace_entities.json")
    tags = [e for e in entities if e.get("workspace_id") == workspace_id and e.get("entity_type") == "tag"]

    if archived is not None:
        tags = [t for t in tags if bool(t.get("archived")) == archived]
    if status is not None:
        tags = [t for t in tags if t.get("status") == status]

    def _k_dt(s):
        if not isinstance(s, str):
            return ""
        return s

    if sort == "name_asc":
        tags.sort(key=lambda r: ((r.get("name") or "").casefold(), r.get("id") or ""))
    elif sort == "name_desc":
        tags.sort(key=lambda r: ((r.get("name") or "").casefold(), r.get("id") or ""), reverse=True)
    elif sort == "created_at_asc":
        tags.sort(key=lambda r: (_k_dt(r.get("created_at")), r.get("id") or ""))
    elif sort == "created_at_desc":
        tags.sort(key=lambda r: (_k_dt(r.get("created_at")), r.get("id") or ""), reverse=True)
    elif sort == "updated_at_asc":
        tags.sort(key=lambda r: (_k_dt(r.get("updated_at")), r.get("id") or ""))
    else:  # updated_at_desc
        tags.sort(key=lambda r: (_k_dt(r.get("updated_at")), r.get("id") or ""), reverse=True)

    total = len(tags)
    page = tags[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor({"offset": next_offset}) if has_more else None

    _log_and_enforce(conn.get("id"), "get_tags", "OK", t0)

    return {
        "tags": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }

