        if conn:
            _log_and_enforce(conn.get("id"), "create_tag", "VALIDATION_ERROR", t0)
        return _err("VALIDATION_ERROR", "archived must be boolean")

    conns = _load("clockify_connections.json")
    conn = _pick_active_connection(conns)
    if not conn:
        return _err("UNAUTHORIZED", "No active Clockify connection available")

    limited = _log_and_enforce(conn.get("id"), "create_tag", "PENDING", t0)
    if isinstance(limited, tuple) and limited[0] == "__err__":
        return limited[1]

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id and w.get("connection_id") == conn.get("id")), None)
    if not ws:
        _log_and_enforce(conn.get("id"), "create_tag", "NOT_FOUND", t0)
        return _err("NOT_FOUND", "Workspace not found for active connection", workspace_id=workspace_id)
    if ws.get("status") != "active":
        _log_and_enforce(conn.get("id"), "create_tag", "UNAUTHORIZED", t0)
        return _err("UNAUTHORIZED", "Workspace is not active")

    entities = _load("workspace_entities.json")

    # Unique(workspace_id, entity_type, external_id) will be satisfied by new external id.
    # Also avoid duplicate tag names? Not required by schema; allow.
    now = _now()
    new_id = _new_ulid("clk_ent_")
    external_id = "ext_tag_" + hashlib.sha256((workspace_id + "|" + new_id).encode("utf-8")).hexdigest()[:24]

    # Provider create: in this offline server, treat as always successful; if it were to fail we'd not commit.
    row = {
        "id": new_id,
        "workspace_id": workspace_id,
        "entity_type": "tag",
        "external_id": external_id,
        "name": name.strip(),
        "email": None,
        "project_id": None,
        "client_id": None,
        "billable": None,
        "archived": bool(archived) if archived is not None else False,
        "color": color.strip() if isinstance(color, str) else None,
        "status": "active" if not (bool(archived) if archived is not None else False) else "archived",
        "raw": {"provider": "clockify", "created_via": "create_tag"},
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    # Constraints: name non-empty for tag; already validated.
    entities.append(row)
    _save("workspace_entities.json", entities)

    # update connection success
    for c in conns:
        if c.get("id") == conn.get("id"):
            c["last_success_at"] = _iso(_now())
            c["updated_at"] = _iso(_now())
            break
    _save("clockify_connections.json", conns)

    _log_and_enforce(conn.get("id"), "create_tag", "OK", t0)

    return {"tag": row}

def detailed_report(workspace_id, time_from, time_to, filters=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0487000" if __import__("os").path.isdir("./environment_mix/0487000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s, field):
        if not isinstance(s, str) or not s:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 date-time string")
        try:
            # accept trailing Z
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"Malformed timestamp for {field}")

    def _ulidish(pat, v, field):
        if not isinstance(v, str) or re.match(pat, v) is None:
            return _err("VALIDATION_ERROR", f"{field} is malformed")
        return None

    def _sanitize_connection_row(r):
        if not isinstance(r, dict):
            return r
        out = dict(r)
        if "api_key_ciphertext" in out:
            out.pop("api_key_ciphertext", None)
        return out

    def _log(endpoint, connection_id, status_code, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": _now_iso(),
            "endpoint": endpoint,
            "connection_id": connection_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(connection_id, want_report=False, want_api_calls=0):
        # Optional; only enforced if rate_limits.json exists and has expected shape
        cfgs = _load("rate_limits.json")
        cfg = None
        if isinstance(cfgs, dict):
            cfg = cfgs
        elif isinstance(cfgs, list) and cfgs:
            # pick first matching connection_id else first
            for c in cfgs:
                if isinstance(c, dict) and c.get("connection_id") == connection_id:
                    cfg = c
                    break
            if cfg is None and isinstance(cfgs[0], dict):
                cfg = cfgs[0]
        if not isinstance(cfg, dict):
            return None  # limits disabled/not configured

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.now(datetime.timezone.utc)

        def _parse_log_ts(x):
            if not isinstance(x, str):
                return None
            try:
                if x.endswith("Z"):
                    x = x[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(x)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except ValueError:
                return None

        per_min = cfg.get("max_api_calls_per_minute")
        per_hour = cfg.get("max_report_generations_per_hour")
        ttl_s = cfg.get("report_cache_ttl_seconds", 900)

        # Count API calls in last 60s (we approximate each report generation as want_api_calls calls)
        if per_min is not None and want_api_calls:
            try:
                per_min = int(per_min)
            except Exception:
                per_min = None
        if per_hour is not None and want_report:
            try:
                per_hour = int(per_hour)
            except Exception:
                per_hour = None

        if per_min is not None and want_api_calls:
            cutoff = now - datetime.timedelta(seconds=60)
            used = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("connection_id") != connection_id:
                    continue
                ts = _parse_log_ts(r.get("ts"))
                if ts is None or ts < cutoff:
                    continue
                meta = r.get("meta") or {}
                if isinstance(meta, dict):
                    used += int(meta.get("api_calls", 0) or 0)
            if used + want_api_calls > per_min:
                return _err("RATE_LIMIT", "Clockify API rate limit exceeded", limit="max_api_calls_per_minute", window_seconds=60)

        if per_hour is not None and want_report:
            cutoff = now - datetime.timedelta(seconds=3600)
            gens = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("connection_id") != connection_id:
                    continue
                ts = _parse_log_ts(r.get("ts"))
                if ts is None or ts < cutoff:
                    continue
                meta = r.get("meta") or {}
                if isinstance(meta, dict) and meta.get("report_generation") is True:
                    if r.get("status") in (200, 201):
                        gens += 1
            if gens + 1 > per_hour:
                return _err("QUOTA_EXCEEDED", "Report generation quota exceeded", limit="max_report_generations_per_hour", window_seconds=3600)

        return None

    # Validate inputs
    e = _ulidish(r"^clk_wsp_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id, "workspace_id")
    if e:
        _log("detailed_report", None, 400, "VALIDATION_ERROR")
        return e
    tf, e = _parse_dt(time_from, "time_from")
    if e:
        _log("detailed_report", None, 400, "VALIDATION_ERROR")
        return e
    tt, e = _parse_dt(time_to, "time_to")
    if e:
        _log("detailed_report", None, 400, "VALIDATION_ERROR")
        return e
    if tt < tf:
        _log("detailed_report", None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "time_to must be greater than or equal to time_from")
    if filters is not None and not isinstance(filters, dict):
        _log("detailed_report", None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "filters must be an object when provided")

    conns = _load("clockify_connections.json")
    if not isinstance(conns, list):
        conns = []
    active_conn = None
    for c in conns:
        if isinstance(c, dict) and c.get("provider") == "clockify" and c.get("status") == "active":
            active_conn = c
            break
    if active_conn is None:
        _log("detailed_report", None, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Clockify connection available")

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    wsp = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == workspace_id:
            wsp = w
            break
    if wsp is None:
        _log("detailed_report", active_conn.get("id"), 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")
    if wsp.get("connection_id") != active_conn.get("id"):
        _log("detailed_report", active_conn.get("id"), 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not accessible for the active connection")

    # Enforce quotas/rate-limits if configured
    limit_err = _enforce_limits(active_conn.get("id"), want_report=True, want_api_calls=1)
    if limit_err:
        _log("detailed_report", active_conn.get("id"), 429, limit_err["error"]["code"], meta={"report_generation": True, "api_calls": 1})
        return limit_err

    # Resolve user entity for requested_by_user_entity_id: must exist in same workspace
    ents = _load("workspace_entities.json")
    if not isinstance(ents, list):
        ents = []
    user_ent = None
    for r in ents:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") == workspace_id and r.get("entity_type") == "user" and r.get("external_id") == active_conn.get("external_user_id"):
            user_ent = r
            break
    if user_ent is None:
        # For report tools, require existing mapping; avoid implicit upsert here (business rule only mentions get_user).
        _log("detailed_report", active_conn.get("id"), 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No user mapping found in workspace for the active connection")

    # Cache: reuse completed report with identical parameters within TTL if configured
    reports = _load("reports.json")
    if not isinstance(reports, list):
        reports = []

    # Normalize filters for stable cache key
    filters_norm = filters if filters is not None else None
    try:
        filters_key = json.dumps(filters_norm, sort_keys=True, separators=(",", ":")) if filters_norm is not None else ""
    except TypeError:
        _log("detailed_report", active_conn.get("id"), 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "filters must be JSON-serializable")

    req_fingerprint = hashlib.sha256(
        ("detailed|" + workspace_id + "|" + tf.isoformat() + "|" + tt.isoformat() + "|" + filters_key).encode("utf-8")
    ).hexdigest()

    # TTL from rate_limits config if present
    ttl_seconds = 900
    cfgs = _load("rate_limits.json")
    cfg = None
    if isinstance(cfgs, dict):
        cfg = cfgs
    elif isinstance(cfgs, list) and cfgs:
        for c in cfgs:
            if isinstance(c, dict) and c.get("connection_id") == active_conn.get("id"):
                cfg = c
                break
        if cfg is None and isinstance(cfgs[0], dict):
            cfg = cfgs[0]
    if isinstance(cfg, dict) and cfg.get("report_cache_ttl_seconds") is not None:
        try:
            ttl_seconds = int(cfg.get("report_cache_ttl_seconds"))
        except Exception:
            ttl_seconds = 900

    def _dt_from_iso(x):
        if not isinstance(x, str):
            return None
        try:
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            d = datetime.datetime.fromisoformat(x)
            if d.tzinfo is None:
                d = d.replace(tzinfo=datetime.timezone.utc)
            return d.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    cached = None
    now = datetime.datetime.now(datetime.timezone.utc)
    for r in reports:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if r.get("report_type") != "detailed":
            continue
        if r.get("status") != "completed":
            continue
        # Check same parameters
        if (r.get("time_from") or "") != tf.isoformat():
            continue
        if (r.get("time_to") or "") != tt.isoformat():
            continue
        try:
            rk = json.dumps(r.get("filters"), sort_keys=True, separators=(",", ":")) if r.get("filters") is not None else ""
        except TypeError:
            rk = None
        if rk != filters_key:
            continue
        created = _dt_from_iso(r.get("created_at"))
        if created is None:
            continue
        if (now - created).total_seconds() <= ttl_seconds:
            cached = r
            break

    if cached is not None:
        _log("detailed_report", active_conn.get("id"), 200, None, meta={"cached": True, "report_generation": False, "api_calls": 0})
        return {
            "report": cached,
            "cached": True,
            "meta": {
                "workspace_id": workspace_id,
                "report_type": "detailed",
                "time_from": tf.isoformat(),
                "time_to": tt.isoformat(),
                "fingerprint": req_fingerprint
            }
        }

    # Create report row: queued -> running -> completed/failed
    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        x = (ms << 16) ^ (os.getpid() & 0xFFFF) ^ (len(reports) & 0xFFFF)
        out = []
        for _ in range(16):
            out.append(alphabet[x % 32])
            x //= 32
        return f"{prefix}_{''.join(reversed(out))}"

    report_id = _new_id("clk_rpt")
    created_at = _now_iso()
    base = {
        "id": report_id,
        "workspace_id": workspace_id,
        "requested_by_user_entity_id": user_ent.get("id"),
        "report_type": "detailed",
        "time_from": tf.isoformat(),
        "time_to": tt.isoformat(),
        "filters": filters_norm,
        "status": "queued",
        "result": None,
        "error_message": None,
        "created_at": created_at,
        "updated_at": created_at
    }
    reports.append(base)
    _save("reports.json", reports)

    # Transition to running
    base["status"] = "running"
    base["updated_at"] = _now_iso()
    _save("reports.json", reports)

    # Build detailed rows from local time_entries with filters
    entries = _load("time_entries.json")
    if not isinstance(entries, list):
        entries = []

    ent_by_id = {e.get("id"): e for e in ents if isinstance(e, dict) and e.get("workspace_id") == workspace_id}

    def _passes_filters(te):
        if filters_norm is None:
            return True
        f = filters_norm

        # supported keys: project_entity_ids, client_entity_ids, user_entity_ids, tag_entity_ids, billable
        if "billable" in f:
            if not isinstance(f["billable"], bool):
                return False
            if bool(te.get("billable")) != f["billable"]:
                return False

        def _as_set(key):
            v = f.get(key)
            if v is None:
                return None
            if not isinstance(v, list) or not all(isinstance(x, str) for x in v):
                return "__bad__"
            return set(v)

        for key, field in [
            ("project_entity_ids", "project_entity_id"),
            ("client_entity_ids", "client_entity_id"),
            ("user_entity_ids", "user_entity_id"),
        ]:
            s = _as_set(key)
            if s == "__bad__":
                return False
            if s is not None:
                if te.get(field) not in s:
                    return False

        tag_s = _as_set("tag_entity_ids")
        if tag_s == "__bad__":
            return False
        if tag_s is not None:
            te_tags = te.get("tag_entity_ids") or []
            if not isinstance(te_tags, list):
                return False
            if not tag_s.issubset(set([x for x in te_tags if isinstance(x, str)])):
                return False

        return True

    def _iso(x):
        return x if isinstance(x, str) else None

    def _dt(x):
        if not isinstance(x, str):
            return None
        try:
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            d = datetime.datetime.fromisoformat(x)
            if d.tzinfo is None:
                d = d.replace(tzinfo=datetime.timezone.utc)
            return d.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    try:
        rows = []
        total_seconds = 0
        for te in entries:
            if not isinstance(te, dict):
                continue
            if te.get("workspace_id") != workspace_id:
                continue
            if te.get("status") == "deleted":
                continue

            # time window: include entries overlapping [tf, tt)
            sdt = _dt(te.get("start_at"))
            if sdt is None:
                continue
            edt = _dt(te.get("end_at")) if te.get("end_at") is not None else None
            # treat running as ending at now for reporting window intersection
            eff_end = edt if edt is not None else now
            if eff_end <= tf or sdt >= tt:
                continue

            if not _passes_filters(te):
                continue

            dur = te.get("duration_seconds")
            if isinstance(dur, int) and dur >= 0:
                dur_s = dur
            else:
                # compute overlap duration if stopped but missing duration, or running
                overlap_start = max(sdt, tf)
                overlap_end = min(eff_end, tt)
                dur_s = int(max(0, (overlap_end - overlap_start).total_seconds()))

            total_seconds += dur_s

            def _name_for(eid):
                if not eid:
                    return None
                ent = ent_by_id.get(eid)
                if not isinstance(ent, dict):
                    return None
                return ent.get("name") or ent.get("email")

            rows.append({
                "time_entry_id": te.get("id"),
                "external_time_entry_id": te.get("external_time_entry_id"),
                "user_entity_id": te.get("user_entity_id"),
                "user_name": _name_for(te.get("user_entity_id")),
                "project_entity_id": te.get("project_entity_id"),
                "project_name": _name_for(te.get("project_entity_id")),
                "task_entity_id": te.get("task_entity_id"),
                "task_name": _name_for(te.get("task_entity_id")),
                "client_entity_id": te.get("client_entity_id"),
                "client_name": _name_for(te.get("client_entity_id")),
                "description": te.get("description"),
                "billable": bool(te.get("billable")),
                "start_at": _iso(te.get("start_at")),
                "end_at": _iso(te.get("end_at")),
                "status": te.get("status"),
                "source": te.get("source"),
                "duration_seconds": dur_s,
                "tag_entity_ids": te.get("tag_entity_ids") if isinstance(te.get("tag_entity_ids"), list) else []
            })

        # Deterministic ordering by start_at then id
        rows.sort(key=lambda r: ((r.get("start_at") or ""), (r.get("time_entry_id") or "")))

        result = {
            "report_type": "detailed",
            "workspace_id": workspace_id,
            "time_from": tf.isoformat(),
            "time_to": tt.isoformat(),
            "filters": filters_norm,
            "total_entries": len(rows),
            "total_duration_seconds": total_seconds,
            "rows": rows
        }

        # Complete report
        base["status"] = "completed"
        base["result"] = result
        base["error_message"] = None
        base["updated_at"] = _now_iso()
        _save("reports.json", reports)

        # update connection last_success_at
        for c in conns:
            if isinstance(c, dict) and c.get("id") == active_conn.get("id"):
                c["last_success_at"] = _now_iso()
                c["updated_at"] = _now_iso()
                break
        _save("clockify_connections.json", conns)

        _log("detailed_report", active_conn.get("id"), 201, None, meta={"cached": False, "report_generation": True, "api_calls": 1})
        return {
            "report": base,
            "cached": False,
            "meta": {
                "workspace_id": workspace_id,
                "report_type": "detailed",
                "time_from": tf.isoformat(),
                "time_to": tt.isoformat(),
                "fingerprint": req_fingerprint
            }
        }

    except Exception as ex:
        # Mark failed with truncated message
        msg = str(ex)
        if len(msg) > 240:
            msg = msg[:240]
        base["status"] = "failed"
        base["error_message"] = msg
        base["result"] = None
        base["updated_at"] = _now_iso()
        _save("reports.json", reports)

        for c in conns:
            if isinstance(c, dict) and c.get("id") == active_conn.get("id"):
                c["last_error_at"] = _now_iso()
                c["last_error_message"] = msg
                c["status"] = "error" if c.get("status") == "active" else c.get("status")
                c["updated_at"] = _now_iso()
                break
        _save("clockify_connections.json", conns)

        _log("detailed_report", active_conn.get("id"), 500, "CONFLICT", meta={"cached": False, "report_generation": True, "api_calls": 1})
        return _err("CONFLICT", "Report generation failed", detail=msg, report_id=report_id)

