        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": _now_iso(),
            "endpoint": endpoint,
            "connection_id": connection_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(connection_id, want_report=False, want_api_calls=0):
        cfgs = _load("rate_limits.json")
        cfg = None
        if isinstance(cfgs, dict):
            cfg = cfgs
        elif isinstance(cfgs, list) and cfgs:
            for c in cfgs:
                if isinstance(c, dict) and c.get("connection_id") == connection_id:
                    cfg = c
                    break
            if cfg is None and isinstance(cfgs[0], dict):
                cfg = cfgs[0]
        if not isinstance(cfg, dict):
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.now(datetime.timezone.utc)

        def _parse_log_ts(x):
            if not isinstance(x, str):
                return None
            try:
                if x.endswith("Z"):
                    x = x[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(x)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except ValueError:
                return None

        per_min = cfg.get("max_api_calls_per_minute")
        per_hour = cfg.get("max_report_generations_per_hour")

        if per_min is not None and want_api_calls:
            try:
                per_min = int(per_min)
            except Exception:
                per_min = None
        if per_hour is not None and want_report:
            try:
                per_hour = int(per_hour)
            except Exception:
                per_hour = None

        if per_min is not None and want_api_calls:
            cutoff = now - datetime.timedelta(seconds=60)
            used = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("connection_id") != connection_id:
                    continue
                ts = _parse_log_ts(r.get("ts"))
                if ts is None or ts < cutoff:
                    continue
                meta = r.get("meta") or {}
                if isinstance(meta, dict):
                    used += int(meta.get("api_calls", 0) or 0)
            if used + want_api_calls > per_min:
                return _err("RATE_LIMIT", "Clockify API rate limit exceeded", limit="max_api_calls_per_minute", window_seconds=60)

        if per_hour is not None and want_report:
            cutoff = now - datetime.timedelta(seconds=3600)
            gens = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("connection_id") != connection_id:
                    continue
                ts = _parse_log_ts(r.get("ts"))
                if ts is None or ts < cutoff:
                    continue
                meta = r.get("meta") or {}
                if isinstance(meta, dict) and meta.get("report_generation") is True:
                    if r.get("status") in (200, 201):
                        gens += 1
            if gens + 1 > per_hour:
                return _err("QUOTA_EXCEEDED", "Report generation quota exceeded", limit="max_report_generations_per_hour", window_seconds=3600)

        return None

    # Validate inputs
    e = _ulidish(r"^clk_wsp_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id, "workspace_id")
    if e:
        _log("summary_report", None, 400, "VALIDATION_ERROR")
        return e
    tf, e = _parse_dt(time_from, "time_from")
    if e:
        _log("summary_report", None, 400, "VALIDATION_ERROR")
        return e
    tt, e = _parse_dt(time_to, "time_to")
    if e:
        _log("summary_report", None, 400, "VALIDATION_ERROR")
        return e
    if tt < tf:
        _log("summary_report", None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "time_to must be greater than or equal to time_from")
    if filters is not None and not isinstance(filters, dict):
        _log("summary_report", None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "filters must be an object when provided")

    conns = _load("clockify_connections.json")
    if not isinstance(conns, list):
        conns = []
    active_conn = None
    for c in conns:
        if isinstance(c, dict) and c.get("provider") == "clockify" and c.get("status") == "active":
            active_conn = c
            break
    if active_conn is None:
        _log("summary_report", None, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Clockify connection available")

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    wsp = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == workspace_id:
            wsp = w
            break
    if wsp is None:
        _log("summary_report", active_conn.get("id"), 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")
    if wsp.get("connection_id") != active_conn.get("id"):
        _log("summary_report", active_conn.get("id"), 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not accessible for the active connection")

    limit_err = _enforce_limits(active_conn.get("id"), want_report=True, want_api_calls=1)
    if limit_err:
        _log("summary_report", active_conn.get("id"), 429, limit_err["error"]["code"], meta={"report_generation": True, "api_calls": 1})
        return limit_err

    ents = _load("workspace_entities.json")
    if not isinstance(ents, list):
        ents = []
    user_ent = None
    for r in ents:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") == workspace_id and r.get("entity_type") == "user" and r.get("external_id") == active_conn.get("external_user_id"):
            user_ent = r
            break
    if user_ent is None:
        _log("summary_report", active_conn.get("id"), 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No user mapping found in workspace for the active connection")

    reports = _load("reports.json")
    if not isinstance(reports, list):
        reports = []

    filters_norm = filters if filters is not None else None
    try:
        filters_key = json.dumps(filters_norm, sort_keys=True, separators=(",", ":")) if filters_norm is not None else ""
    except TypeError:
        _log("summary_report", active_conn.get("id"), 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "filters must be JSON-serializable")

    req_fingerprint = hashlib.sha256(
        ("summary|" + workspace_id + "|" + tf.isoformat() + "|" + tt.isoformat() + "|" + filters_key).encode("utf-8")
    ).hexdigest()

    ttl_seconds = 900
    cfgs = _load("rate_limits.json")
    cfg = None
    if isinstance(cfgs, dict):
        cfg = cfgs
    elif isinstance(cfgs, list) and cfgs:
        for c in cfgs:
            if isinstance(c, dict) and c.get("connection_id") == active_conn.get("id"):
                cfg = c
                break
        if cfg is None and isinstance(cfgs[0], dict):
            cfg = cfgs[0]
    if isinstance(cfg, dict) and cfg.get("report_cache_ttl_seconds") is not None:
        try:
            ttl_seconds = int(cfg.get("report_cache_ttl_seconds"))
        except Exception:
            ttl_seconds = 900

    def _dt_from_iso(x):
        if not isinstance(x, str):
            return None
        try:
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            d = datetime.datetime.fromisoformat(x)
            if d.tzinfo is None:
                d = d.replace(tzinfo=datetime.timezone.utc)
            return d.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    cached = None
    now = datetime.datetime.now(datetime.timezone.utc)
    for r in reports:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if r.get("report_type") != "summary":
            continue
        if r.get("status") != "completed":
            continue
        if (r.get("time_from") or "") != tf.isoformat():
            continue
        if (r.get("time_to") or "") != tt.isoformat():
            continue
        try:
            rk = json.dumps(r.get("filters"), sort_keys=True, separators=(",", ":")) if r.get("filters") is not None else ""
        except TypeError:
            rk = None
        if rk != filters_key:
            continue
        created = _dt_from_iso(r.get("created_at"))
        if created is None:
            continue
        if (now - created).total_seconds() <= ttl_seconds:
            cached = r
            break

    if cached is not None:
        _log("summary_report", active_conn.get("id"), 200, None, meta={"cached": True, "report_generation": False, "api_calls": 0})
        return {
            "report": cached,
            "cached": True,
            "meta": {
                "workspace_id": workspace_id,
                "report_type": "summary",
                "time_from": tf.isoformat(),
                "time_to": tt.isoformat(),
                "fingerprint": req_fingerprint
            }
        }

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        x = (ms << 16) ^ (os.getpid() & 0xFFFF) ^ (len(reports) & 0xFFFF)
        out = []
        for _ in range(16):
            out.append(alphabet[x % 32])
            x //= 32
        return f"{prefix}_{''.join(reversed(out))}"

    report_id = _new_id("clk_rpt")
    created_at = _now_iso()
    base = {
        "id": report_id,
        "workspace_id": workspace_id,
        "requested_by_user_entity_id": user_ent.get("id"),
        "report_type": "summary",
        "time_from": tf.isoformat(),
        "time_to": tt.isoformat(),
        "filters": filters_norm,
        "status": "queued",
        "result": None,
        "error_message": None,
        "created_at": created_at,
        "updated_at": created_at
    }
    reports.append(base)
    _save("reports.json", reports)

    base["status"] = "running"
    base["updated_at"] = _now_iso()
    _save("reports.json", reports)

    entries = _load("time_entries.json")
    if not isinstance(entries, list):
        entries = []

    ent_by_id = {e.get("id"): e for e in ents if isinstance(e, dict) and e.get("workspace_id") == workspace_id}

    def _passes_filters(te):
        if filters_norm is None:
            return True
        f = filters_norm

        if "billable" in f:
            if not isinstance(f["billable"], bool):
                return False
            if bool(te.get("billable")) != f["billable"]:
                return False

        def _as_set(key):
            v = f.get(key)
            if v is None:
                return None
            if not isinstance(v, list) or not all(isinstance(x, str) for x in v):
                return "__bad__"
            return set(v)

        for key, field in [
            ("project_entity_ids", "project_entity_id"),
            ("client_entity_ids", "client_entity_id"),
            ("user_entity_ids", "user_entity_id"),
        ]:
            s = _as_set(key)
            if s == "__bad__":
                return False
            if s is not None:
                if te.get(field) not in s:
                    return False

        tag_s = _as_set("tag_entity_ids")
        if tag_s == "__bad__":
            return False
        if tag_s is not None:
            te_tags = te.get("tag_entity_ids") or []
            if not isinstance(te_tags, list):
                return False
            if not tag_s.issubset(set([x for x in te_tags if isinstance(x, str)])):
                return False

        return True

    def _dt(x):
        if not isinstance(x, str):
            return None
        try:
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            d = datetime.datetime.fromisoformat(x)
            if d.tzinfo is None:
                d = d.replace(tzinfo=datetime.timezone.utc)
            return d.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    try:
        # Summary groups by project, client, user
        groups = {}
        total_seconds = 0
        total_entries = 0

        def _name_for(eid):
            if not eid:
                return None
            ent = ent_by_id.get(eid)
            if not isinstance(ent, dict):
                return None
            return ent.get("name") or ent.get("email")

        for te in entries:
            if not isinstance(te, dict):
                continue
            if te.get("workspace_id") != workspace_id:
                continue
            if te.get("status") == "deleted":
                continue

            sdt = _dt(te.get("start_at"))
            if sdt is None:
                continue
            edt = _dt(te.get("end_at")) if te.get("end_at") is not None else None
            eff_end = edt if edt is not None else now
            if eff_end <= tf or sdt >= tt:
                continue

            if not _passes_filters(te):
                continue

            dur = te.get("duration_seconds")
            if isinstance(dur, int) and dur >= 0:
                dur_s = dur
            else:
                overlap_start = max(sdt, tf)
                overlap_end = min(eff_end, tt)
                dur_s = int(max(0, (overlap_end - overlap_start).total_seconds()))

            key = (
                te.get("project_entity_id") or "",
                te.get("client_entity_id") or "",
                te.get("user_entity_id") or ""
            )
            g = groups.get(key)
            if g is None:
                g = {
                    "project_entity_id": te.get("project_entity_id"),
                    "project_name": _name_for(te.get("project_entity_id")),
                    "client_entity_id": te.get("client_entity_id"),
                    "client_name": _name_for(te.get("client_entity_id")),
                    "user_entity_id": te.get("user_entity_id"),
                    "user_name": _name_for(te.get("user_entity_id")),
                    "total_duration_seconds": 0,
                    "entry_count": 0,
                    "billable_duration_seconds": 0
                }
                groups[key] = g
            g["total_duration_seconds"] += dur_s
            g["entry_count"] += 1
            if bool(te.get("billable")):
                g["billable_duration_seconds"] += dur_s

            total_seconds += dur_s
            total_entries += 1

        group_rows = list(groups.values())
        group_rows.sort(key=lambda r: (-(r.get("total_duration_seconds") or 0), (r.get("project_name") or ""), (r.get("user_name") or ""), (r.get("client_name") or "")))

        result = {
            "report_type": "summary",
            "workspace_id": workspace_id,
            "time_from": tf.isoformat(),
            "time_to": tt.isoformat(),
            "filters": filters_norm,
            "total_entries": total_entries,
            "total_duration_seconds": total_seconds,
            "groups": group_rows
        }

        base["status"] = "completed"
        base["result"] = result
        base["error_message"] = None
        base["updated_at"] = _now_iso()
        _save("reports.json", reports)

        for c in conns:
            if isinstance(c, dict) and c.get("id") == active_conn.get("id"):
                c["last_success_at"] = _now_iso()
                c["updated_at"] = _now_iso()
                break
        _save("clockify_connections.json", conns)

        _log("summary_report", active_conn.get("id"), 201, None, meta={"cached": False, "report_generation": True, "api_calls": 1})
        return {
            "report": base,
            "cached": False,
            "meta": {
                "workspace_id": workspace_id,
                "report_type": "summary",
                "time_from": tf.isoformat(),
                "time_to": tt.isoformat(),
                "fingerprint": req_fingerprint
            }
        }

    except Exception as ex:
        msg = str(ex)
        if len(msg) > 240:
            msg = msg[:240]
        base["status"] = "failed"
        base["error_message"] = msg
        base["result"] = None
        base["updated_at"] = _now_iso()
        _save("reports.json", reports)

        for c in conns:
            if isinstance(c, dict) and c.get("id") == active_conn.get("id"):
                c["last_error_at"] = _now_iso()
                c["last_error_message"] = msg
                c["status"] = "error" if c.get("status") == "active" else c.get("status")
                c["updated_at"] = _now_iso()
                break
        _save("clockify_connections.json", conns)

        _log("summary_report", active_conn.get("id"), 500, "CONFLICT", meta={"cached": False, "report_generation": True, "api_calls": 1})
        return _err("CONFLICT", "Report generation failed", detail=msg, report_id=report_id)

def test_clockify_connection(connection_id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0487000" if __import__("os").path.isdir("./environment_mix/0487000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(endpoint, connection_id2, status_code, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": _now_iso(),
            "endpoint": endpoint,
            "connection_id": connection_id2,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(connection_id, str) or re.match(r"^clk_conn_[0-9A-HJKMNP-TV-Z]{10,}$", connection_id) is None:
        _log("test_clockify_connection", None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "connection_id is malformed")

    conns = _load("clockify_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = None
    for c in conns:
        if isinstance(c, dict) and c.get("id") == connection_id:
            conn = c
            break
    if conn is None:
        _log("test_clockify_connection", connection_id, 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Connection not found")

    # "Test" by checking required persisted fields exist; we cannot call Clockify offline.
    # If api_key_ciphertext missing -> mark error; else mark success.
    now = _now_iso()
    ok = isinstance(conn.get("api_key_ciphertext"), str) and bool(conn.get("api_key_ciphertext"))
    if ok and isinstance(conn.get("external_user_id"), str) and conn.get("external_user_id"):
        conn["last_success_at"] = now
        conn["last_error_at"] = None
        conn["last_error_message"] = None
        # if previously error and transition allows, revive to active
        if conn.get("status") == "error":
            conn["status"] = "active"
        conn["updated_at"] = now
        _save("clockify_connections.json", conns)

        _log("test_clockify_connection", connection_id, 200, None, meta={"api_calls": 1})
        return {
            "connection": {k: v for k, v in conn.items() if k != "api_key_ciphertext"},
            "user": {
                "external_user_id": conn.get("external_user_id"),
                "external_user_email": conn.get("external_user_email")
            },
            "status": "ok"
        }

    msg = "Missing or invalid connection credentials/user mapping"
    conn["last_error_at"] = now
    conn["last_error_message"] = msg[:240]
    # Transition active -> error is allowed
    if conn.get("status") == "active":
        conn["status"] = "error"
    conn["updated_at"] = now
    _save("clockify_connections.json", conns)

    _log("test_clockify_connection", connection_id, 200, None, meta={"api_calls": 1, "status": "error"})
    return {
        "connection": {k: v for k, v in conn.items() if k != "api_key_ciphertext"},
        "user": {
            "external_user_id": conn.get("external_user_id"),
            "external_user_email": conn.get("external_user_email")
        },
        "status": "error",
        "message": msg
    }

def get_connection(connection_id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0487000" if __import__("os").path.isdir("./environment_mix/0487000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(endpoint, connection_id2, status_code, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": _now_iso(),
            "endpoint": endpoint,
            "connection_id": connection_id2,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(connection_id, str) or re.match(r"^clk_conn_[0-9A-Z]+$", connection_id) is None:
        _log("get_connection", None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "connection_id is malformed")

    # Optional rate limiting if configured
    cfgs = _load("rate_limits.json")
    cfg = None
    if isinstance(cfgs, dict):
        cfg = cfgs
    elif isinstance(cfgs, list) and cfgs and isinstance(cfgs[0], dict):
        cfg = cfgs[0]

    if isinstance(cfg, dict) and cfg.get("max_api_calls_per_minute") is not None:
        try:
            per_min = int(cfg.get("max_api_calls_per_minute"))
        except Exception:
            per_min = None
        if per_min is not None:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            now = datetime.datetime.now(datetime.timezone.utc)
            cutoff = now - datetime.timedelta(seconds=60)

            def _parse_log_ts(x):
                if not isinstance(x, str):
                    return None
                try:
                    if x.endswith("Z"):
                        x = x[:-1] + "+00:00"
                    dt = datetime.datetime.fromisoformat(x)
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                    return dt.astimezone(datetime.timezone.utc)
                except ValueError:
                    return None

            used = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("connection_id") != connection_id:
                    continue
                ts = _parse_log_ts(r.get("ts"))
                if ts is None or ts < cutoff:
                    continue
                meta = r.get("meta") or {}
                if isinstance(meta, dict):
                    used += int(meta.get("api_calls", 0) or 0)
            if used + 1 > per_min:
                _log("get_connection", connection_id, 429, "RATE_LIMIT", meta={"api_calls": 1})
                return _err("RATE_LIMIT", "Clockify API rate limit exceeded", limit="max_api_calls_per_minute", window_seconds=60)

    conns = _load("clockify_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = None
    for c in conns:
        if isinstance(c, dict) and c.get("id") == connection_id:
            conn = c
            break
    if conn is None:
        _log("get_connection", connection_id, 404, "NOT_FOUND", meta={"api_calls": 0})
        return _err("NOT_FOUND", "Connection not found")

    # Ambient auth: permitted if any active connection exists AND it matches requested connection,
    # or if requested connection is the active one.
    active = None
    for c in conns:
        if isinstance(c, dict) and c.get("provider") == "clockify" and c.get("status") == "active":
            active = c
            break
    if active is None or active.get("id") != connection_id:
        # No credential passed; treat as not permitted to view other connections.
        _log("get_connection", connection_id, 401, "UNAUTHORIZED", meta={"api_calls": 0})
        return _err("UNAUTHORIZED", "Not permitted to view this connection")

    out = {k: v for k, v in conn.items() if k != "api_key_ciphertext"}
    _log("get_connection", connection_id, 200, None, meta={"api_calls": 0})
    return {"connection": out}

def update_connection(connection_id, status=None, default_workspace_id=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0487000" if __import__("os").path.isdir("./environment_mix/0487000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_connection"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        v = s.strip()
        try:
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(v)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _ensure_logs_collection():
        candidates = ["request_logs.json", "api_requests.json", "usage_logs.json", "audit_logs.json"]
        for fn in candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _log(connection_id_used, status_code, error_code=None, extra=None):
        fn = _ensure_logs_collection()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{connection_id_used}|{now.isoformat()}|{time.time()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "connection_id": connection_id_used,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(fn, logs)

    # validate
    if not isinstance(connection_id, str) or not re.match(r"^clk_conn_[0-9A-Z]+$", connection_id):
        _log(None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid connection_id.")
    if status is not None and status not in ["active", "revoked", "error"]:
        _log(connection_id, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status.")
    if default_workspace_id is not None:
        if not isinstance(default_workspace_id, str) or not re.match(r"^clk_wsp_[0-9A-Z]+$", default_workspace_id):
            _log(connection_id, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid default_workspace_id.")

    conns = _load("clockify_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id), None)
    if not conn:
        _log(connection_id, 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Connection not found.")

    # enforce immutable identity fields: provider/external_user_id cannot change (not in params anyway)
    now = _now_utc()

    # validate default_workspace_id reference if provided
    if default_workspace_id is not None:
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == default_workspace_id), None)
        if not ws:
            _log(connection_id, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "default_workspace_id does not reference an existing workspace.")
        if ws.get("connection_id") != connection_id:
            _log(connection_id, 409, "CONFLICT")
            return _err("CONFLICT", "default_workspace_id must belong to the same connection.")

    # lifecycle transition validation
    if status is not None and status != conn.get("status"):
        cur = conn.get("status")
        allowed = {
            "active": ["error", "revoked"],
            "error": ["active", "revoked"],
            "revoked": [],
        }
        if cur not in allowed or status not in allowed[cur]:
            _log(connection_id, 409, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Illegal status transition from '{cur}' to '{status}'.")

        conn["status"] = status
        # clear error fields when moving to active
        if status == "active":
            conn["last_error_at"] = None
            conn["last_error_message"] = None

    if default_workspace_id is not None:
        conn["default_workspace_id"] = default_workspace_id

    conn["updated_at"] = _iso(now)

    _save("clockify_connections.json", conns)
    _log(connection_id, 200, None)
    # never return api_key_ciphertext
    out = dict(conn)
    if "api_key_ciphertext" in out:
        out.pop("api_key_ciphertext", None)
    return {"connection": out}

def get_project(workspace_id, project_id, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0487000" if __import__("os").path.isdir("./environment_mix/0487000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_project"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(datetime.datetime.utcnow().timestamp() * 1000)
        h = hashlib.sha256((str(ts) + os.urandom(16).hex()).encode("utf-8")).digest()
        v = ts
        out = []
        for _ in range(10):
            out.append(alphabet[v % 32])
            v //= 32
        out = list(reversed(out))
        r = int.from_bytes(h[:10], "big")
        rand = []
        for _ in range(16):
            rand.append(alphabet[r % 32])
            r //= 32
        return prefix + "_" + "".join(out + rand)

    def _log(status_code, connection_id_used=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _ulid("clk_rl"),
            "ts": _now(),
            "endpoint": endpoint,
            "connection_id": connection_id_used,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    def _enforce_limits(connection_row):
        cfg = _load("rate_limits.json")
        if isinstance(cfg, dict):
            max_api_per_min = cfg.get("max_clockify_api_calls_per_minute")
            enabled = cfg.get("enabled", True)
        elif isinstance(cfg, list) and cfg and isinstance(cfg[0], dict):
            enabled = cfg[0].get("enabled", True)
            max_api_per_min = cfg[0].get("max_clockify_api_calls_per_minute")
        else:
            enabled = False
            max_api_per_min = None
        if not enabled:
            return None
        if not isinstance(max_api_per_min, int) or max_api_per_min <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.utcnow()
        window_start = now_dt - datetime.timedelta(minutes=1)
        cnt = 0
        for r in logs:
            if r.get("connection_id") != connection_row.get("id"):
                continue
            ts = _parse_iso(r.get("ts"))
            if ts is None:
                continue
            if ts >= window_start:
                cnt += 1
        if cnt >= max_api_per_min:
            return _err("RATE_LIMIT", "Clockify API rate limit exceeded for this connection.", limit=max_api_per_min, window_seconds=60)
        return None

    # validate
    if not isinstance(workspace_id, str) or not re.match(r"^clk_wsp_[0-9A-Z]+$", workspace_id):
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id is malformed.", field="workspace_id")
    if not isinstance(project_id, str) or not re.match(r"^clk_ent_[0-9A-Z]+$", project_id):
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is malformed.", field="project_id")

    conns = _load("clockify_connections.json")
    if not isinstance(conns, list):
        conns = []
    active_conns = [c for c in conns if c.get("provider") == "clockify" and c.get("status") == "active"]
    if not active_conns:
        _log(401, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Clockify connection is available for this operation.")

    ws = _load("workspaces.json")
    if not isinstance(ws, list):
        ws = []
    wrow = next((w for w in ws if w.get("id") == workspace_id), None)
    if wrow is None:
        _log(404, None, "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    conn = next((c for c in active_conns if c.get("id") == wrow.get("connection_id")), None)
    if conn is None:
        _log(401, wrow.get("connection_id"), "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not accessible with an active Clockify connection.")

    limerr = _enforce_limits(conn)
    if limerr:
        _log(429, conn.get("id"), limerr["error"]["code"])
        return limerr

    ents = _load("workspace_entities.json")
    if not isinstance(ents, list):
        ents = []
    proj = next((e for e in ents if e.get("id") == project_id and e.get("workspace_id") == workspace_id and e.get("entity_type") == "project"), None)
    if proj is None:
        _log(404, conn.get("id"), "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found in the specified workspace.", project_id=project_id, workspace_id=workspace_id)

    _log(200, conn.get("id"), None)
    return {"project": proj}

