            _log(400, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "color must be a hex RGB string like #RRGGBB.", field="color")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            _log(400, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status is invalid.", field="status")

    # auth/connection context
    conns = _load("clockify_connections.json")
    if not isinstance(conns, list):
        conns = []
    active_conns = [c for c in conns if c.get("provider") == "clockify" and c.get("status") == "active"]
    if not active_conns:
        _log(401, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Clockify connection is available for this operation.")

    ws = _load("workspaces.json")
    if not isinstance(ws, list):
        ws = []
    wrow = next((w for w in ws if w.get("id") == workspace_id), None)
    if wrow is None:
        _log(404, None, "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    conn = next((c for c in active_conns if c.get("id") == wrow.get("connection_id")), None)
    if conn is None:
        _log(401, wrow.get("connection_id"), "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not accessible with an active Clockify connection.")

    limerr = _enforce_limits(conn)
    if limerr:
        _log(429, conn.get("id"), limerr["error"]["code"])
        return limerr

    ents = _load("workspace_entities.json")
    if not isinstance(ents, list):
        ents = []

    proj = next((e for e in ents if e.get("id") == project_id and e.get("workspace_id") == workspace_id and e.get("entity_type") == "project"), None)
    if proj is None:
        _log(404, conn.get("id"), "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found in the specified workspace.", project_id=project_id, workspace_id=workspace_id)

    # validate client reference if provided (nullable supports clear via explicit None; but signature uses None default)
    if client_id is not None:
        client = next((e for e in ents if e.get("id") == client_id and e.get("workspace_id") == workspace_id), None)
        if client is None or client.get("entity_type") != "client":
            _log(400, conn.get("id"), "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "client_id must reference a client entity in the same workspace.", field="client_id")

    # lifecycle transition validation
    if status is not None and status != proj.get("status"):
        transitions = {
            "active": set(["archived", "deleted"]),
            "archived": set(["active", "deleted"]),
            "deleted": set([]),
        }
        cur = proj.get("status")
        if cur not in transitions or status not in transitions[cur]:
            _log(409, conn.get("id"), "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Illegal project status transition.", from_status=cur, to_status=status)

    # If attempting to "hard delete": schema says soft-delete; also cannot hard delete if referenced.
    # This endpoint only sets workspace_entities.status; we never remove rows.
    # Still enforce rule: referenced projects cannot be hard-deleted; we soft-delete by status='deleted' regardless.
    referenced = False
    tes = _load("time_entries.json")
    if not isinstance(tes, list):
        tes = []
    for te in tes:
        if te.get("workspace_id") == workspace_id and te.get("project_entity_id") == project_id and te.get("status") != "deleted":
            referenced = True
            break

    # apply updates
    now = _now()
    changed = False

    if name is not None and name != proj.get("name"):
        proj["name"] = name
        changed = True

    # client_id: parameter semantics allow "set to null to clear" in API.
    # With this signature, client_id=None could mean "not provided" or "clear".
    # We'll only clear when caller explicitly passes client_id=None by including the key; not possible here.
    # So: if client_id is not None, set; otherwise do not change.
    if client_id is not None and client_id != proj.get("client_id"):
        proj["client_id"] = client_id
        changed = True

    if billable is not None and billable != proj.get("billable"):
        proj["billable"] = billable
        changed = True

    if color is not None and color != proj.get("color"):
        proj["color"] = color
        changed = True

    if status is not None and status != proj.get("status"):
        # soft-delete regardless; referenced just means we must not remove, which we never do.
        if status == "deleted" and referenced:
            proj["status"] = "deleted"
            changed = True
        else:
            proj["status"] = status
            changed = True

    if not changed:
        _log(409, conn.get("id"), "CONFLICT")
        return _err("CONFLICT", "No changes requested; project remains unchanged.", project_id=project_id)

    proj["updated_at"] = now

    # persist
    for i, e in enumerate(ents):
        if e.get("id") == project_id:
            ents[i] = proj
            break
    _save("workspace_entities.json", ents)

    _log(200, conn.get("id"), None)
    return {"project": proj}

def update_time_entry(workspace_id, time_entry_id, description=None, project_entity_id=None, task_entity_id=None, client_entity_id=None, billable=None, tag_entity_ids=None, start_at=None, end_at=None, status=None, **_extra):
