        return "request_logs.json"

    def _append_request_log(connection_id, ok, status_code, error_code=None, error_message=None):
        fn = _find_request_log_filename()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        now = _now()
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex[:24],
            "timestamp": _iso(now),
            "ts": _iso(now),
            "endpoint": endpoint,
            "connection_id": connection_id,
            "status": status_code,
            "ok": bool(ok),
            "latency_ms": latency_ms,
        }
        if error_code:
            row["error_code"] = error_code
        if error_message:
            row["error_message"] = (str(error_message)[:500] if error_message is not None else None)
        logs.append(row)
        _save(fn, logs)

    def _rate_limits_for_connection(connection_id):
        # Attempt to read config if present; otherwise keep permissive defaults.
        cfg = {}
        for fn in ("limits.json", "rate_limits.json", "quota.json", "config.json", "settings.json"):
            p = os.path.join(_DB, fn)
            if os.path.exists(p):
                try:
                    with open(p, encoding="utf-8") as f:
                        cfg = json.load(f) or {}
                except Exception:
                    cfg = {}
                break

        # Defaults: no enforced limit unless configured, but still log.
        api_per_min = None
        reports_per_hour = None

        # Support a few plausible shapes.
        # e.g. {"clockify":{"api_calls_per_minute":60,"reports_per_hour":10}}
        clockify = cfg.get("clockify") if isinstance(cfg, dict) else None
        if isinstance(clockify, dict):
            api_per_min = clockify.get("api_calls_per_minute", api_per_min)
            reports_per_hour = clockify.get("reports_per_hour", reports_per_hour)

        # e.g. {"api_calls_per_minute":60,"report_generations_per_hour":10}
        if isinstance(cfg, dict):
            api_per_min = cfg.get("api_calls_per_minute", api_per_min)
            reports_per_hour = cfg.get("report_generations_per_hour", reports_per_hour)

        # For this endpoint, treat it as a provider API call.
        return api_per_min, reports_per_hour

    def _enforce_rate_limit(connection_id):
        api_per_min, _reports_per_hour = _rate_limits_for_connection(connection_id)
        if not api_per_min:
            return None  # no limit configured
        if not isinstance(api_per_min, int) or api_per_min <= 0:
            return None

        fn = _find_request_log_filename()
        logs = _load(fn)
        if not isinstance(logs, list):
            return None

        now = _now()
        window_start = now - datetime.timedelta(minutes=1)
        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("connection_id") != connection_id:
                continue
            if r.get("endpoint") is None:
                continue
            ts = r.get("timestamp") or r.get("ts")
            if not isinstance(ts, str):
                continue
            dt, perr = _parse_dt(ts, "timestamp")
            if perr is not None or dt is None:
                continue
            if dt >= window_start:
                # Count all API calls (reads included) as "Clockify API calls per minute" per rule
                count += 1
        if count >= api_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded for this connection (api calls per minute)", limit=api_per_min, window_seconds=60)
        return None

    # ----------------- Validate inputs -----------------
    try:
        if not isinstance(workspace_id, str) or not workspace_id:
            # log later once connection resolved (or unknown)
            return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string")
        if not re.match(r"^clk_wsp_[0-9A-Z]+$", workspace_id):
            return _err("VALIDATION_ERROR", "workspace_id must match ^clk_wsp_[0-9A-Z]+$")

        if not isinstance(time_entry_id, str) or not time_entry_id:
            return _err("VALIDATION_ERROR", "time_entry_id must be a non-empty string")
        # IMPORTANT: do not reject if pattern mismatches; real backend finds by id and returns NOT_FOUND.
        # Only validate type/non-empty here.

        if description is not None:
            if not isinstance(description, str):
                return _err("VALIDATION_ERROR", "description must be a string")
            if len(description) > 5000:
                return _err("VALIDATION_ERROR", "description must be at most 5000 characters")

        def _validate_ent_id(val, field):
            if val is None:
                return None
            if not isinstance(val, str) or not val:
                return _err("VALIDATION_ERROR", f"{field} must be a non-empty string or null")
            if not re.match(r"^clk_ent_[0-9A-Z]+$", val):
                return _err("VALIDATION_ERROR", f"{field} must match ^clk_ent_[0-9A-Z]+$")
            return None

        for fld, v in (("project_entity_id", project_entity_id), ("task_entity_id", task_entity_id), ("client_entity_id", client_entity_id)):
            e = _validate_ent_id(v, fld)
            if e:
                return e

        if billable is not None and not isinstance(billable, bool):
            return _err("VALIDATION_ERROR", "billable must be a boolean")

        if tag_entity_ids is not None:
            if not isinstance(tag_entity_ids, list):
                return _err("VALIDATION_ERROR", "tag_entity_ids must be an array of strings")
            if len(tag_entity_ids) > 200:
                return _err("VALIDATION_ERROR", "tag_entity_ids must have at most 200 items")
            for i, tid in enumerate(tag_entity_ids):
                if not isinstance(tid, str) or not tid:
                    return _err("VALIDATION_ERROR", f"tag_entity_ids[{i}] must be a non-empty string")
                if not re.match(r"^clk_ent_[0-9A-Z]+$", tid):
                    return _err("VALIDATION_ERROR", f"tag_entity_ids[{i}] must match ^clk_ent_[0-9A-Z]+$")

        start_dt, perr = _parse_dt(start_at, "start_at")
        if perr:
            return perr
        end_dt, perr = _parse_dt(end_at, "end_at")
        if perr:
            return perr

        if status is not None:
            if not isinstance(status, str):
                return _err("VALIDATION_ERROR", "status must be a string")
            if status not in ("running", "stopped", "deleted"):
                return _err("VALIDATION_ERROR", "status must be one of: running, stopped, deleted")
    except Exception as e:
        return _err("VALIDATION_ERROR", "Invalid input", detail=str(e))

    # ----------------- Resolve active connection (ambient auth) -----------------
    try:
        conns = _load("clockify_connections.json")
        if not isinstance(conns, list):
            conns = []
    except Exception as e:
        return _err("NOT_FOUND", "Datastore unavailable", detail=str(e))

    active_conn = None
    for c in conns:
        if isinstance(c, dict) and c.get("provider") == "clockify" and c.get("status") == "active":
            active_conn = c
            break

    # For this tool, must have active connection
    if not active_conn:
        # cannot log with a specific connection_id
        return _err("UNAUTHORIZED", "No active Clockify connection available")

    connection_id = active_conn.get("id")

    # Enforce rate limit before doing work; still log after decision
    rl = _enforce_rate_limit(connection_id)
    if rl:
        _append_request_log(connection_id, ok=False, status_code=429, error_code=rl["error"]["code"], error_message=rl["error"]["message"])
        return rl

    # ----------------- Load referenced collections -----------------
    try:
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        entities = _load("workspace_entities.json")
        if not isinstance(entities, list):
            entities = []
        time_entries = _load("time_entries.json")
        if not isinstance(time_entries, list):
            time_entries = []
    except Exception as e:
        _append_request_log(connection_id, ok=False, status_code=500, error_code="NOT_FOUND", error_message=str(e))
        return _err("NOT_FOUND", "Datastore unavailable", detail=str(e))

    wsp = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not wsp:
        _append_request_log(connection_id, ok=False, status_code=404, error_code="NOT_FOUND", error_message="Workspace not found")
        return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)
    if wsp.get("connection_id") != connection_id:
        _append_request_log(connection_id, ok=False, status_code=401, error_code="UNAUTHORIZED", error_message="Workspace does not belong to active connection")
        return _err("UNAUTHORIZED", "Workspace does not belong to the active connection")

    te = next((r for r in time_entries if isinstance(r, dict) and r.get("id") == time_entry_id and r.get("workspace_id") == workspace_id), None)
    if not te:
        _append_request_log(connection_id, ok=False, status_code=404, error_code="NOT_FOUND", error_message="Time entry not found in workspace")
        return _err("NOT_FOUND", "Time entry not found", workspace_id=workspace_id, time_entry_id=time_entry_id)

    # ----------------- Apply business rules / validations -----------------
    # Lifecycle transition: only running|stopped -> deleted supported
    if status is not None and status != te.get("status"):
        cur = te.get("status")
        if status == "deleted" and cur in ("running", "stopped"):
            pass
        else:
            _append_request_log(connection_id, ok=False, status_code=409, error_code="INVALID_TRANSITION", error_message=f"Cannot transition status from {cur} to {status}")
            return _err("INVALID_TRANSITION", f"Illegal status transition: {cur} -> {status}")

    # If entry is running, refuse time bounds edits (and status change except delete)
    is_running = (te.get("status") == "running")
    if is_running:
        if start_at is not None or end_at is not None:
            _append_request_log(connection_id, ok=False, status_code=400, error_code="INVALID_TRANSITION", error_message="Cannot edit start/end while entry is running")
            return _err("INVALID_TRANSITION", "Cannot edit start_at/end_at while time entry is running; stop it first")
        if status is not None and status != "deleted":
            _append_request_log(connection_id, ok=False, status_code=400, error_code="INVALID_TRANSITION", error_message="Only delete allowed for running entry")
            return _err("INVALID_TRANSITION", "Only transition supported for a running entry is running -> deleted")

    # Resolve and validate entities within this workspace
    ent_by_id = {e.get("id"): e for e in entities if isinstance(e, dict) and e.get("workspace_id") == workspace_id}

    def _must_be_entity(eid, etype, field):
        if eid is None:
            return None, None
        e = ent_by_id.get(eid)
        if not e:
            return None, _err("NOT_FOUND", f"{field} not found", id=eid)
        if e.get("entity_type") != etype:
            return None, _err("VALIDATION_ERROR", f"{field} must reference a '{etype}' entity in this workspace")
        if e.get("status") == "deleted":
            return None, _err("CONFLICT", f"{field} references a deleted entity", id=eid)
        return e, None

    # Validate tags
    if tag_entity_ids is not None:
        seen = set()
        for tid in tag_entity_ids:
            if tid in seen:
                continue
            seen.add(tid)
            e, err = _must_be_entity(tid, "tag", "tag_entity_ids")
            if err:
                _append_request_log(connection_id, ok=False, status_code=400 if err["error"]["code"] == "VALIDATION_ERROR" else 404, error_code=err["error"]["code"], error_message=err["error"]["message"])
                return err

    # Validate project/task/client according to constraints
    proj = None
    task = None
    client = None

    if project_entity_id is not None:
        proj, err = _must_be_entity(project_entity_id, "project", "project_entity_id")
        if err:
            _append_request_log(connection_id, ok=False, status_code=400 if err["error"]["code"] == "VALIDATION_ERROR" else 404, error_code=err["error"]["code"], error_message=err["error"]["message"])
            return err

    if client_entity_id is not None:
        client, err = _must_be_entity(client_entity_id, "client", "client_entity_id")
        if err:
            _append_request_log(connection_id, ok=False, status_code=400 if err["error"]["code"] == "VALIDATION_ERROR" else 404, error_code=err["error"]["code"], error_message=err["error"]["message"])
            return err

    # Task requires project (either provided now, or existing if not clearing)
    # If caller sets task_entity_id (non-null), ensure project exists after update and task belongs to it.
    if task_entity_id is not None:
        # If explicitly clearing task (None), ok; but here it's not None due to branch.
        task, err = _must_be_entity(task_entity_id, "task", "task_entity_id")
        if err:
            _append_request_log(connection_id, ok=False, status_code=400 if err["error"]["code"] == "VALIDATION_ERROR" else 404, error_code=err["error"]["code"], error_message=err["error"]["message"])
            return err

        # Determine the effective project after update:
        effective_project_id = project_entity_id if project_entity_id is not None else te.get("project_entity_id")
        if not effective_project_id:
            _append_request_log(connection_id, ok=False, status_code=400, error_code="VALIDATION_ERROR", error_message="task requires project")
            return _err("VALIDATION_ERROR", "task_entity_id requires project_entity_id (time entry must have a project to set a task)")
        effective_proj = ent_by_id.get(effective_project_id)
        if not effective_proj or effective_proj.get("entity_type") != "project":
            _append_request_log(connection_id, ok=False, status_code=400, error_code="VALIDATION_ERROR", error_message="effective project invalid")
            return _err("VALIDATION_ERROR", "project_entity_id must reference a 'project' entity in this workspace")
        if task.get("project_id") != effective_project_id:
            _append_request_log(connection_id, ok=False, status_code=409, error_code="CONFLICT", error_message="task does not belong to project")
            return _err("CONFLICT", "task_entity_id must belong to the selected project (workspace_entities.task.project_id must equal project_entity_id)")

    # If time bounds are edited, entry must be stopped
    if start_at is not None or end_at is not None:
        if te.get("status") != "stopped":
            _append_request_log(connection_id, ok=False, status_code=400, error_code="INVALID_TRANSITION", error_message="Cannot edit time bounds unless stopped")
            return _err("INVALID_TRANSITION", "start_at/end_at may only be edited when the time entry is stopped")
        # Apply invariants: end >= start when both set (use effective values)
        eff_start = start_dt if start_dt is not None else _parse_dt(te.get("start_at"), "start_at")[0] if isinstance(te.get("start_at"), str) else None
        eff_end = end_dt if end_dt is not None else _parse_dt(te.get("end_at"), "end_at")[0] if isinstance(te.get("end_at"), str) else None
        if eff_start is None:
            _append_request_log(connection_id, ok=False, status_code=400, error_code="VALIDATION_ERROR", error_message="Missing start time")
            return _err("VALIDATION_ERROR", "start_at is required (existing entry missing start_at)")
        if eff_end is not None and eff_end < eff_start:
            _append_request_log(connection_id, ok=False, status_code=400, error_code="VALIDATION_ERROR", error_message="end before start")
            return _err("VALIDATION_ERROR", "end_at must be greater than or equal to start_at")

    # ----------------- Mutate and persist -----------------
    # No success without effect: require at least one change
    changed = False
    now = _now()

    def _set(field, value):
        nonlocal changed
        if te.get(field) != value:
            te[field] = value
            changed = True

    if description is not None:
        _set("description", description)

    if billable is not None:
        _set("billable", billable)

    if project_entity_id is not None:
        _set("project_entity_id", project_entity_id)
        # Clearing/Changing project implies task may be invalid; if project cleared, also clear task.
        if project_entity_id is None and te.get("task_entity_id") is not None:
            _set("task_entity_id", None)

    if task_entity_id is not None:
        _set("task_entity_id", task_entity_id)

    if client_entity_id is not None:
        _set("client_entity_id", client_entity_id)

    if tag_entity_ids is not None:
        # Store as provided (dedupe while preserving order)
        deduped = []
        seen = set()
        for tid in tag_entity_ids:
            if tid in seen:
                continue
            seen.add(tid)
            deduped.append(tid)
        _set("tag_entity_ids", deduped)

    if start_dt is not None:
        _set("start_at", _iso(start_dt))
    if end_dt is not None:
        _set("end_at", _iso(end_dt))

    # If stopped and has both times, recompute duration_seconds
    if te.get("status") == "stopped":
        sdt, _ = _parse_dt(te.get("start_at"), "start_at")
        edt, _ = _parse_dt(te.get("end_at"), "end_at")
        if sdt is not None and edt is not None:
            dur = int((edt - sdt).total_seconds())
            if dur < 0:
                _append_request_log(connection_id, ok=False, status_code=400, error_code="VALIDATION_ERROR", error_message="Computed negative duration")
                return _err("VALIDATION_ERROR", "end_at must be greater than or equal to start_at")
            _set("duration_seconds", dur)

    if status is not None and status != te.get("status"):
        # only deleted transition validated above
        _set("status", status)
        if status == "deleted":
            # keep referential integrity by soft-delete; also clear running invariants
            _set("end_at", te.get("end_at"))  # leave as-is
            if te.get("status") == "deleted":
                pass

    if changed:
        te["updated_at"] = _iso(now)
        # enforce invariants for running
        if te.get("status") == "running":
            te["end_at"] = None
            te["duration_seconds"] = None

        _save("time_entries.json", time_entries)
        # mark connection success
        for c in conns:
            if isinstance(c, dict) and c.get("id") == connection_id:
                c["last_success_at"] = _iso(now)
                c["updated_at"] = _iso(now)
                break
        _save("clockify_connections.json", conns)

        # Never return ciphertext; time entry has none. Return updated record.
        _append_request_log(connection_id, ok=True, status_code=200)
        return {"time_entry": te}
    else:
        # Matched row but no effect => treat as idempotent success with current representation
        _append_request_log(connection_id, ok=True, status_code=200)
        return {"time_entry": te}

def whoami(connection_id=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0487000" if __import__("os").path.isdir("./environment_mix/0487000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- load datastore ----
    conns = _load("clockify_connections.json")
    workspaces = _load("workspaces.json")
    reports = _load("reports.json")

    # Optional collections for service dynamics (may not exist in schema batch)
    request_logs = _load("request_logs.json")
    usage = _load("usage_counters.json")

    # ---- helpers ----
    def _log(status, conn_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "whoami",
            "connection_id": conn_id,
            "status": status,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": latency_ms,
        }
        request_logs.append(row)
        _save("request_logs.json", request_logs)

    def _find_conn_by_id_or_active(cid):
        if cid is not None:
            for c in conns:
                if c.get("id") == cid:
                    return c
            return None
        # active connection: deterministic by created_at then id
        active = [c for c in conns if c.get("provider") == "clockify" and c.get("status") == "active"]
        active.sort(key=lambda x: (x.get("created_at") or "", x.get("id") or ""))
        return active[0] if active else None

    def _default_workspace_for_connection(conn):
        if not conn:
            return None
        ws = [w for w in workspaces if w.get("connection_id") == conn.get("id")]
        if not ws:
            return None
        # default_workspace_id preferred if exists
        dws_id = conn.get("default_workspace_id")
        if dws_id:
            for w in ws:
                if w.get("id") == dws_id:
                    return w
        # otherwise first active by name (deterministic)
        active_ws = [w for w in ws if w.get("status") == "active"]
        active_ws.sort(key=lambda x: ((x.get("name") or "").lower(), x.get("id") or ""))
        return active_ws[0] if active_ws else None

    def _count_requests(conn_id, window_seconds):
        if not conn_id:
            return 0
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_seconds)

        def _parse_ts(ts):
            if not ts or not isinstance(ts, str):
                return None
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        n = 0
        for r in request_logs:
            if r.get("connection_id") != conn_id:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts and ts >= cutoff:
                n += 1
        return n

    def _count_reports_generated(conn_id, window_seconds):
        if not conn_id:
            return 0
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_seconds)

        def _parse_ts(ts):
            if not ts or not isinstance(ts, str):
                return None
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        # reports are per-workspace; infer connection via workspace.connection_id
        ws_by_id = {w.get("id"): w for w in workspaces}
        n = 0
        for rep in reports:
            ws = ws_by_id.get(rep.get("workspace_id"))
            if not ws or ws.get("connection_id") != conn_id:
                continue
            ts = _parse_ts(rep.get("created_at"))
            if ts and ts >= cutoff:
                n += 1
        return n

    # ---- input validation ----
    if connection_id is not None:
        if not isinstance(connection_id, str):
            _log("error", None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "connection_id must be a string")
        if not re.match(r"^clk_conn_[0-9A-Z]+$", connection_id):
            _log("error", None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "connection_id must match ^clk_conn_[0-9A-Z]+$")

    # ---- resolve auth / identity context ----
    conn = _find_conn_by_id_or_active(connection_id)
    if connection_id is not None and conn is None:
        _log("error", connection_id, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No such connection or not accessible in this server context", connection_id=connection_id)

    # "whoami" should refuse when no valid caller identity present. In this local store,
    # that means no connection at all can be resolved.
    if conn is None:
        _log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated identity (no active connection found)")

    # Entitlements/scopes: inferred from store and role if present
    dws = _default_workspace_for_connection(conn)
    role = dws.get("membership_role") if dws else None

    # Rate-limit/quota consumption: per business rules, per connection_id.
    # Limits are "if enabled"; schema does not declare config. We report consumption and null limits.
    calls_last_minute = _count_requests(conn.get("id"), 60)
    reports_last_hour = _count_reports_generated(conn.get("id"), 3600)

    # Optionally maintain a simple usage counter file (if present); keep it monotonic.
    # This is not required by schema, but ensures observable service dynamics if caller inspects it.
    # We do not enforce any limit here; whoami is an informational endpoint.
    if isinstance(usage, list):
        # store as list of rows by connection_id for simplicity
        u = None
        for row in usage:
            if row.get("connection_id") == conn.get("id"):
                u = row
                break
        if u is None:
            u = {
                "connection_id": conn.get("id"),
                "whoami_calls": 0,
                "last_seen_at": None,
                "updated_at": now,
            }
            usage.append(u)
        u["whoami_calls"] = int(u.get("whoami_calls") or 0) + 1
        u["last_seen_at"] = now
        u["updated_at"] = now
        _save("usage_counters.json", usage)

    # Never return api_key_ciphertext
    conn_public = {k: v for k, v in conn.items() if k != "api_key_ciphertext"}

    # effective workspace selection and permissions
    permissions = {
        "can_read": True,
        "can_write": True,
        "role": role or "unknown",
    }
    # Conservative: if workspace role known and is 'user', treat admin-only operations as false.
    permissions["can_admin"] = True if role in (None, "unknown", "owner", "admin") else False

    body = {
        "identity": {
            "provider": conn_public.get("provider"),
            "connection": conn_public,
            "external_user_id": conn_public.get("external_user_id"),
            "external_user_email": conn_public.get("external_user_email"),
            "effective_workspace": dws if dws else None,
        },
        "entitlements": {
            "permissions": permissions,
        },
        "rate_limits": {
            "per_connection": {
                "clockify_api_calls": {
                    "window_seconds": 60,
                    "used": calls_last_minute,
                    "limit": None,
                },
                "report_generations": {
                    "window_seconds": 3600,
                    "used": reports_last_hour,
                    "limit": None,
                },
            }
        },
        "server_time": now,
    }

    _log("ok", conn.get("id"), None)
    return {"ok": True, "data": body}
